fn ate_ability_type_change(
    ability: engine_data::abilities_table::AbilityId,
    move_type: engine_data::type_chart::Type,
    move_id: u16,
) -> Option<engine_data::type_chart::Type> {
    use engine_data::abilities_table::ability_ids;
    use engine_data::type_chart::Type;

    if NO_MODIFY_TYPE.contains(&move_id) || is_damaging_z(move_id) {
        return None;
    }
    if ability == ability_ids::NORMALIZE {
        return Some(Type::Normal);
    }
    if move_type != Type::Normal {
        return None;
    }
    match ability {
        ability_ids::PIXILATE => Some(Type::Fairy),
        ability_ids::AERILATE => Some(Type::Flying),
        ability_ids::REFRIGERATE => Some(Type::Ice),
        ability_ids::DRAGONIZE => Some(Type::Dragon),
        ability_ids::GALVANIZE => Some(Type::Electric),
        _ => None,
    }
}


const NO_MODIFY_TYPE: [u16; 9] = [
    moves_table::move_ids::HIDDENPOWER,
    moves_table::move_ids::JUDGMENT,
    moves_table::move_ids::MULTIATTACK,
    moves_table::move_ids::NATURALGIFT,
    moves_table::move_ids::REVELATIONDANCE,
    moves_table::move_ids::STRUGGLE,
    moves_table::move_ids::TECHNOBLAST,
    moves_table::move_ids::TERRAINPULSE,
    moves_table::move_ids::WEATHERBALL,
];










fn weather_ball_type(move_id: u16, weather: crate::field::Weather) -> Option<engine_data::type_chart::Type> {
    use crate::field::Weather;
    use engine_data::type_chart::Type;
    if move_id != moves_table::move_ids::WEATHERBALL {
        return None;
    }

    match weather.reader() {
        Weather::Sun => Some(Type::Fire),
        Weather::Rain => Some(Type::Water),
        Weather::Sand => Some(Type::Rock),
        Weather::Snow | Weather::Hail => Some(Type::Ice),
        _ => None,
    }
}








fn identified_effectiveness(chart: &damage::TypeChart, defender: &Mon, move_id: u16, move_type: engine_data::type_chart::Type, effectiveness: Effectiveness) -> Effectiveness {
    use engine_data::type_chart::Type;
    if effectiveness != Effectiveness::Immune {
        return effectiveness;
    }
    let c = &defender.volatiles.conds;
    let negated = if c.has(crate::mon::condition_ids::FORESIGHT) && matches!(move_type, Type::Normal | Type::Fighting) {
        Type::Ghost
    } else if c.has(crate::mon::condition_ids::MIRACLEEYE) && move_type == Type::Psychic {
        Type::Dark
    } else if defender.effective_item() == engine_data::items_table::item_ids::RINGTARGET {

        return move_effectiveness(chart, 
            move_id,
            move_type,
            defender.types.map(|t| t.filter(|&ty| crate::damage::type_effectiveness(chart, move_type, [Some(ty), None]) != Effectiveness::Immune)),
        );
    } else {
        return effectiveness;
    };
    move_effectiveness(chart, move_id, move_type, defender.types.map(|t| if t == Some(negated) { None } else { t }))
}


fn identified_evasion(m: &Mon) -> i8 {
    let e = m.boosts[6];
    if e > 0 && (m.volatiles.conds.has(crate::mon::condition_ids::FORESIGHT) || m.volatiles.conds.has(crate::mon::condition_ids::MIRACLEEYE)) { 0 } else { e }
}


fn ignores_defense_and_evasion(move_id: u16) -> bool {
    matches!(move_id, moves_table::move_ids::DARKESTLARIAT | moves_table::move_ids::SACREDSWORD | moves_table::move_ids::CHIPAWAY)
}





fn grounded_flying_effectiveness(chart: &damage::TypeChart, move_id: u16, move_type: engine_data::type_chart::Type, defender: &Mon) -> Option<Effectiveness> {
    use engine_data::type_chart::Type;
    if move_type != Type::Ground
        || !defender.types.contains(&Some(Type::Flying))
        || defender.effective_item() == engine_data::items_table::item_ids::IRONBALL
        || !(defender.volatiles.has(volatile_flags::GRAVITY) || defender.volatiles.has(volatile_flags::SMACKED_DOWN) || defender.volatiles.has(volatile_flags::INGRAIN))
    {
        return None;
    }
    Some(move_effectiveness(chart, move_id, move_type, defender.types.map(|t| if t == Some(Type::Flying) { None } else { t })))
}



fn thousand_arrows_effectiveness(move_id: u16, move_type: engine_data::type_chart::Type, defender: &Mon) -> Option<Effectiveness> {
    (move_id == moves_table::move_ids::THOUSANDARROWS
        && move_type == engine_data::type_chart::Type::Ground
        && !is_grounded(defender)
        && defender.types.contains(&Some(engine_data::type_chart::Type::Flying)))
    .then_some(Effectiveness::Normal(0))
}

fn move_effectiveness<const N: usize>(chart: &damage::TypeChart, move_id: u16, move_type: engine_data::type_chart::Type, types: [Option<engine_data::type_chart::Type>; N]) -> Effectiveness {
    use engine_data::type_chart::Type;

    if move_id == moves_table::move_ids::STRUGGLE {
        return Effectiveness::Normal(0);
    }

    if move_id == moves_table::move_ids::FLYINGPRESS {
        let mut stage: i32 = 0;
        for ty in types.into_iter().flatten() {
            match (damage::type_effectiveness(chart, move_type, [Some(ty), None]), damage::type_effectiveness(chart, Type::Flying, [Some(ty), None])) {
                (Effectiveness::Immune, _) => return Effectiveness::Immune,
                (Effectiveness::Normal(a), Effectiveness::Normal(b)) => stage += a as i32 + b as i32,
                (Effectiveness::Normal(a), Effectiveness::Immune) => stage += a as i32,
            }
        }
        return Effectiveness::Normal(stage.clamp(-6, 6) as i8);
    }
    if move_id != moves_table::move_ids::FREEZEDRY || !types.contains(&Some(Type::Water)) {
        return damage::type_effectiveness(chart, move_type, types);
    }
    let mut stage: i32 = 0;
    for ty in types.into_iter().flatten() {
        if ty == Type::Water {
            stage += 1;
        } else {
            match damage::type_effectiveness(chart, move_type, [Some(ty), None]) {
                Effectiveness::Immune => return Effectiveness::Immune,
                Effectiveness::Normal(s) => stage += s as i32,
            }
        }
    }
    Effectiveness::Normal(stage.clamp(-6, 6) as i8)
}


fn rising_voltage_power_modifier(move_id: u16, battle: &Battle, target: Actor) -> Option<(i64, i64)> {
    (move_id == moves_table::move_ids::RISINGVOLTAGE && battle.field.terrain == crate::field::Terrain::Electric && is_grounded(mon_at(battle, target))).then_some((2, 1))
}












fn tera_base_power_floor(battle: &Battle, m: &Mon, move_id: u16, move_type: engine_data::type_chart::Type, base_power: i64) -> i64 {
    use moves_table::move_ids::*;

    if !m.tera.active || base_power >= 60 || move_id == STRUGGLE {
        return base_power;
    }
    let of_type = if m.tera.tera_type == Some(engine_data::type_chart::Type::Stellar) {
        m.tera.stellar_boosted & (1 << move_type as u32) == 0
    } else {
        m.types.contains(&Some(move_type))
    };
    let dex = battle.move_data(move_id);
    let callback = matches!(
        move_id,
        BEATUP | CRUSHGRIP | DRAGONENERGY | ELECTROBALL | ERUPTION | FLAIL | GRASSKNOT | GYROBALL | HARDPRESS | HEATCRASH | HEAVYSLAM | LOWKICK
            | REVERSAL | SPITUP | WATERSPOUT
    );
    if of_type && dex.priority <= 0 && dex.multihit_max <= 1 && !callback { 60 } else { base_power }
}

fn stab_modifier(m: &Mon, move_id: u16, move_type: engine_data::type_chart::Type) -> ((i64, i64), bool) {
    use engine_data::type_chart::Type;
    if move_id == moves_table::move_ids::STRUGGLE {
        return ((1, 1), false);
    }
    let force = pledge_combo(m, move_id).is_some();
    let has = m.types.contains(&Some(move_type));
    let pre_tera = if m.tera.typed() { m.tera.base_types.contains(&Some(move_type)) } else { has };
    let is_stab = force || has || pre_tera;
    if m.tera.active && m.tera.tera_type == Some(Type::Stellar) {
        if m.tera.stellar_boosted & (1 << move_type as u32) == 0 || m.tera.move_boosted {

            let spends = m.species != engine_data::species_table::species_ids::TERAPAGOSSTELLAR;
            return (if is_stab { (2, 1) } else { (4915, 4096) }, spends);
        }
        return (if is_stab { (3, 2) } else { (1, 1) }, false);
    }
    let mut stab = if is_stab { (3, 2) } else { (1, 1) };
    if m.tera.active && m.tera.tera_type == Some(move_type) && pre_tera {
        stab = (2, 1);
    }
    if m.ability == engine_data::abilities_table::ability_ids::ADAPTABILITY && (force || has) {
        stab = if stab == (2, 1) { (9, 4) } else { (2, 1) };
    }
    (stab, false)
}

fn effective_move_type(battle: &Battle, actor: Actor, move_id: u16, move_data: &MoveData) -> engine_data::type_chart::Type {

    if let Some((t, _)) = pledge_combo(mon_at(battle, actor), move_id) {
        return t;
    }
    let (earlier, ate) = move_type_changes(battle, actor, move_id, move_data);
    let t = electrified_type(battle, actor, move_id).unwrap_or(earlier.or(ate).unwrap_or(move_data.move_type));

    if battle.field.ion_deluge && t == engine_data::type_chart::Type::Normal {
        engine_data::type_chart::Type::Electric
    } else {
        t
    }
}



fn move_type_changes(
    battle: &Battle,
    actor: Actor,
    move_id: u16,
    move_data: &MoveData,
) -> (Option<engine_data::type_chart::Type>, Option<engine_data::type_chart::Type>) {
    let earlier = weather_ball_type(move_id, weather_for(battle, actor))
        .or(natural_gift_type(battle, actor, move_id))
        .or(terrain_pulse_type(move_id, battle, actor))
        .or(forme_move_type(move_id, mon_at(battle, actor).species))
        .or(plate_drive_move_type(move_id, mon_at(battle, actor)))
        .or(liquid_voice_type(mon_at(battle, actor).ability, move_data.sound && !is_dynamaxed(mon_at(battle, actor))))

        .or((move_id == moves_table::move_ids::HIDDENPOWER).then(|| crate::team::hidden_power(mon_at(battle, actor).ivs).0))

        .or(tera_blast_type(mon_at(battle, actor), move_id))
        .or(revelation_dance_type(mon_at(battle, actor), move_id));




    if battle.rules().abilities.normalize == crate::rules::Normalize::TypeOnly
        && mon_at(battle, actor).ability == engine_data::abilities_table::ability_ids::NORMALIZE
    {
        let converts = move_id != moves_table::move_ids::STRUGGLE && battle.move_data(move_id).move_type != engine_data::type_chart::Type::Normal;
        return (if converts { Some(engine_data::type_chart::Type::Normal) } else { earlier }, None);
    }
    let ate = if earlier.is_some() { None } else { ate_ability_type_change(mon_at(battle, actor).ability, move_data.move_type, move_id) };
    (earlier, ate)
}


fn tera_blast_type(m: &Mon, move_id: u16) -> Option<engine_data::type_chart::Type> {
    (move_id == moves_table::move_ids::TERABLAST && m.tera.active).then_some(m.tera.tera_type).flatten()
}



fn revelation_dance_type(m: &Mon, move_id: u16) -> Option<engine_data::type_chart::Type> {
    if move_id != moves_table::move_ids::REVELATIONDANCE {
        return None;
    }
    let first = m.types.into_iter().flatten().next();
    assert!(first.is_some(), "a typeless user's Revelation Dance (a `???` move) is unported");
    first
}



fn natural_gift_type(battle: &Battle, actor: Actor, move_id: u16) -> Option<engine_data::type_chart::Type> {
    if move_id != moves_table::move_ids::NATURALGIFT {
        return None;
    }
    let m = mon_at(battle, actor);
    if let Some(v) = m.volatiles.conds.turns(crate::mon::condition_ids::NATURALGIFT) {
        return Some(engine_data::type_chart::Type::from_index(v & 0x1F));
    }
    natural_gift_of(battle.rules(), m.effective_item()).map(|(t, _)| t)
}


fn natural_gift_of(rules: &crate::rules::Rules, item: engine_data::items_table::ItemId) -> Option<(engine_data::type_chart::Type, u8)> {
    if item == crate::ids::NONE_ID { None } else { rules.natural_gift[item as usize - 1] }
}



fn use_up_item(m: &mut Mon) {
    m.flags.set(mon_flags::USED_ITEM_TURN);
    m.last_item = m.item;
    m.item = crate::ids::NONE_ID;
    m.volatiles.set(volatile_flags::ITEM_CONSUMED);
    m.volatiles.set(volatile_flags::ITEM_USED);
}


fn cure_status(m: &mut Mon) -> bool {
    if m.hp == 0 || m.status == Status::None {
        return false;
    }
    if m.status == Status::Sleep {
        m.volatiles.conds.remove(crate::mon::condition_ids::NIGHTMARE);
    }
    m.status = Status::None;
    m.status_counter = 0;
    true
}


fn fling_secondary(item: engine_data::items_table::ItemId) -> Option<SecondaryEffect> {
    use engine_data::moves_table::Status as S;
    match item {
        engine_data::items_table::item_ids::FLAMEORB => Some(SecondaryEffect::Status(S::Burn)),
        engine_data::items_table::item_ids::TOXICORB => Some(SecondaryEffect::Status(S::Toxic)),
        engine_data::items_table::item_ids::LIGHTBALL => Some(SecondaryEffect::Status(S::Paralysis)),
        engine_data::items_table::item_ids::POISONBARB => Some(SecondaryEffect::Status(S::Poison)),
        engine_data::items_table::item_ids::KINGSROCK | engine_data::items_table::item_ids::RAZORFANG => Some(SecondaryEffect::Flinch),
        _ => None,
    }
}


fn electrified_type(battle: &Battle, actor: Actor, move_id: u16) -> Option<engine_data::type_chart::Type> {
    (mon_at(battle, actor).volatiles.has(volatile_flags::ELECTRIFIED) && move_id != moves_table::move_ids::STRUGGLE).then_some(engine_data::type_chart::Type::Electric)
}





fn plate_drive_move_type(move_id: u16, mon: &Mon) -> Option<engine_data::type_chart::Type> {
    let item = mon.effective_item();
    match move_id {
        moves_table::move_ids::JUDGMENT => crate::items::plate_type(item),
        moves_table::move_ids::TECHNOBLAST => crate::items::drive_type(item),

        moves_table::move_ids::MULTIATTACK => crate::items::memory_type(item),
        _ => None,
    }
}

fn forme_move_type(move_id: u16, species: u16) -> Option<engine_data::type_chart::Type> {
    use engine_data::species_table::species_ids as sp;
    use engine_data::type_chart::Type;
    match move_id {
        moves_table::move_ids::RAGINGBULL => match species {
            sp::TAUROSPALDEACOMBAT => Some(Type::Fighting),
            sp::TAUROSPALDEABLAZE => Some(Type::Fire),
            sp::TAUROSPALDEAAQUA => Some(Type::Water),
            _ => None,
        },
        moves_table::move_ids::AURAWHEEL => Some(if species == sp::MORPEKOHANGRY { Type::Dark } else { Type::Electric }),

        moves_table::move_ids::TERASTARSTORM if species == sp::TERAPAGOSSTELLAR => Some(Type::Stellar),

        moves_table::move_ids::IVYCUDGEL => match species {
            sp::OGERPONWELLSPRING | sp::OGERPONWELLSPRINGTERA => Some(Type::Water),
            sp::OGERPONHEARTHFLAME | sp::OGERPONHEARTHFLAMETERA => Some(Type::Fire),
            sp::OGERPONCORNERSTONE | sp::OGERPONCORNERSTONETERA => Some(Type::Rock),
            _ => None,
        },
        _ => None,
    }
}


fn terrain_pulse_type(move_id: u16, battle: &Battle, actor: Actor) -> Option<engine_data::type_chart::Type> {
    use crate::field::Terrain;
    use engine_data::type_chart::Type;
    if move_id != moves_table::move_ids::TERRAINPULSE || !is_grounded(mon_at(battle, actor)) {
        return None;
    }
    match battle.field.terrain {
        Terrain::Electric => Some(Type::Electric),
        Terrain::Grassy => Some(Type::Grass),
        Terrain::Misty => Some(Type::Fairy),
        Terrain::Psychic => Some(Type::Psychic),
        Terrain::None => None,
    }
}


fn terrain_pulse_power_modifier(move_id: u16, battle: &Battle, actor: Actor) -> Option<(i64, i64)> {
    (move_id == moves_table::move_ids::TERRAINPULSE && battle.field.terrain != crate::field::Terrain::None && is_grounded(mon_at(battle, actor))).then_some((2, 1))
}



fn solar_weakened_modifier(move_id: u16, weather: crate::field::Weather) -> Option<(i64, i64)> {
    (matches!(move_id, moves_table::move_ids::SOLARBEAM | moves_table::move_ids::SOLARBLADE)
        && matches!(weather, crate::field::Weather::Rain | crate::field::Weather::Sand | crate::field::Weather::Snow | crate::field::Weather::Hail))
    .then_some((1, 2))
}


fn field_boosted_modifier(move_id: u16, battle: &Battle, attacker: &Mon) -> Option<(i64, i64)> {
    let boosted = match move_id {
        moves_table::move_ids::MISTYEXPLOSION => battle.field.terrain == crate::field::Terrain::Misty && is_grounded(attacker),
        moves_table::move_ids::GRAVAPPLE => battle.field.gravity_turns > 0,
        _ => false,
    };
    boosted.then_some((3, 2))
}


fn status_doubled_modifier(move_id: u16, attacker: &Mon, defender: &Mon) -> Option<(i64, i64)> {
    let doubled = match move_id {
        moves_table::move_ids::FACADE => !matches!(attacker.status, Status::None | Status::Sleep),
        moves_table::move_ids::VENOSHOCK => matches!(defender.status, Status::Poison | Status::Toxic),
        _ => false,
    };
    doubled.then_some((2, 1))
}






fn battle_base_power(battle: &Battle, actor: Actor, target: Actor, move_id: u16, base_power: i64) -> i64 {
    let speed = |a: Actor| effective_speed(&battle.sides[a.side as usize].side_conditions, mon_at(battle, a), battle.weather(), battle.field.terrain, battle.rules()) as i64;
    match move_id {

        moves_table::move_ids::PRESENT => 40 * mon_at(battle, actor).volatiles.conds.turns(crate::mon::condition_ids::PRESENT).unwrap_or(1).max(1) as i64,

        moves_table::move_ids::NATURALGIFT => mon_at(battle, actor).volatiles.conds.turns(crate::mon::condition_ids::NATURALGIFT).map_or(1, |v| 60 + 10 * (v >> 5) as i64),

        moves_table::move_ids::FLING => {
            let item = mon_at(battle, actor).item;
            if item == crate::ids::NONE_ID { 1 } else { battle.rules().fling_power[item as usize - 1].max(1) as i64 }
        }

        moves_table::move_ids::MAGNITUDE => mon_at(battle, actor).volatiles.conds.turns(crate::mon::condition_ids::MAGNITUDE).unwrap_or(10) as i64,

        moves_table::move_ids::FURYCUTTER => (base_power * (mon_at(battle, actor).volatiles.conds.turns(crate::mon::condition_ids::FURYCUTTER).unwrap_or(1) & 0xF) as i64).clamp(1, 160),

        moves_table::move_ids::ECHOEDVOICE => base_power * battle.field.echoed_voice_mult.max(1) as i64,

        moves_table::move_ids::AVALANCHE | moves_table::move_ids::REVENGE if mon_at(battle, actor).hit_by_this_turn & (1 << (mon_code(battle, target) - 1)) != 0 => base_power * 2,
        moves_table::move_ids::ELECTROBALL => {
            let ratio = if speed(target) == 0 { 0 } else { speed(actor) / speed(target) };
            [40, 60, 80, 120, 150][ratio.min(4) as usize]
        }
        moves_table::move_ids::GYROBALL => {
            if speed(actor) == 0 {
                1
            } else {
                (25 * speed(target) / speed(actor) + 1).min(150)
            }
        }
        moves_table::move_ids::PAYBACK => {
            let t = mon_at(battle, target);
            if t.volatiles.has(volatile_flags::ACTED_THIS_TURN) && t.turns_active > 0 {
                base_power * 2
            } else {
                base_power
            }
        }


        moves_table::move_ids::FISHIOUSREND | moves_table::move_ids::BOLTBEAK => {
            let t = mon_at(battle, target);
            if t.volatiles.has(volatile_flags::ACTED_THIS_TURN) && t.turns_active > 0 {
                base_power
            } else {
                base_power * 2
            }
        }
        _ => base_power,
    }
}

fn weather_ball_power_modifier(move_id: u16, weather: crate::field::Weather) -> Option<(i64, i64)> {
    (move_id == moves_table::move_ids::WEATHERBALL && weather != crate::field::Weather::None).then_some((2, 1))
}






fn last_respects_base_power_modifier(move_id: u16, side: &crate::side::Side) -> Option<(i64, i64)> {
    if move_id != moves_table::move_ids::LASTRESPECTS {
        return None;
    }
    let fainted = side.total_fainted() as i64;
    (fainted > 0).then_some((1 + fainted, 1))
}




fn chain_stall_streak(battle: &mut Battle, actor: Actor) {
    let counter = mon_at(battle, actor).protect_counter;
    mon_at_mut(battle, actor).protect_counter = if counter == 0 { battle.rules().stall_base } else { (counter * battle.rules().stall_factor).min(battle.rules().stall_max) };
    mon_at_mut(battle, actor).volatiles.conds.set(crate::mon::condition_ids::STALL, 2);
}



fn shield_volatile(move_id: u16) -> Option<u64> {
    match move_id {
        moves_table::move_ids::KINGSSHIELD => Some(volatile_flags::KINGSSHIELD),
        moves_table::move_ids::SPIKYSHIELD => Some(volatile_flags::SPIKYSHIELD),
        moves_table::move_ids::BANEFULBUNKER => Some(volatile_flags::BANEFULBUNKER),
        _ => None,
    }
}






pub(crate) fn is_wind_move(move_id: u16) -> bool {
    use moves_table::move_ids::*;
    matches!(
        move_id,
        AIRCUTTER | BLEAKWINDSTORM | BLIZZARD | FAIRYWIND | GUST | HEATWAVE | HURRICANE | ICYWIND | PETALBLIZZARD | SANDSEARSTORM | SANDSTORM
            | SPRINGTIDESTORM | TAILWIND | TWISTER | WHIRLWIND | WILDBOLTSTORM
    )
}

fn contact_made(battle: &Battle, attacker: Actor, contact: bool) -> bool {
    contact && mon_at(battle, attacker).effective_item() != engine_data::items_table::item_ids::PROTECTIVEPADS
}






fn apply_shield_punish(battle: &mut Battle, attacker: Actor, holder: Actor, move_data: &MoveData, rng: &mut Rng) {
    if !contact_made(battle, attacker, move_data.contact) {
        return;
    }
    let (kings, spiky, bunker) = {
        let mon = mon_at(battle, holder);
        (mon.volatiles.has(volatile_flags::KINGSSHIELD), mon.volatiles.has(volatile_flags::SPIKYSHIELD), mon.volatiles.has(volatile_flags::BANEFULBUNKER))
    };
    if kings {
        let drop = battle.rules().move_effects.kings_shield_attack_drop;
        let deltas = crate::abilities::block_external_boosts(battle, holder, attacker, [drop, 0, 0, 0, 0, 0, 0], rng);
        let before = mon_at(battle, attacker).boosts;
        boost_actor_drawn(battle, attacker, deltas, rng);
        crate::abilities::react_to_lowered_since(battle, holder, attacker, before, rng);
    }

    for (cond, drop) in [(crate::mon::condition_ids::SILKTRAP, [0, 0, 0, 0, -1, 0, 0]), (crate::mon::condition_ids::OBSTRUCT, [0, -2, 0, 0, 0, 0, 0])] {
        if mon_at(battle, holder).volatiles.conds.has(cond) {
            let deltas = crate::abilities::block_external_boosts(battle, holder, attacker, drop, rng);
            let before = mon_at(battle, attacker).boosts;
            boost_actor_drawn(battle, attacker, deltas, rng);
            crate::abilities::react_to_lowered_since(battle, holder, attacker, before, rng);
        }
    }

    if spiky {
        damage_event_ties(battle, attacker, rng);
    }
    if spiky && mon_at(battle, attacker).ability != engine_data::abilities_table::ability_ids::MAGICGUARD {
        let damage = (mon_at(battle, attacker).base_max_hp / 8).max(1);
        focus_band_roll_at(battle, attacker, rng);
        apply_damage_at(battle, attacker, damage);
    }


    if bunker {
        let had = mon_at(battle, attacker).status;
        try_set_status(battle, holder, attacker, Status::Poison, rng);
        if had == Status::None && mon_at(battle, attacker).status != Status::None {
            crate::abilities::synchronize_reaction(battle, holder, attacker, Status::Poison, rng);
        }
    }

    if mon_at(battle, holder).volatiles.conds.has(crate::mon::condition_ids::BURNINGBULWARK) {
        let had = mon_at(battle, attacker).status;
        try_set_status(battle, holder, attacker, Status::Burn, rng);
        if had == Status::None && mon_at(battle, attacker).status != Status::None {
            crate::abilities::synchronize_reaction(battle, holder, attacker, Status::Burn, rng);
        }
    }
}





pub fn is_trapped(battle: &Battle, actor: Actor) -> bool {
    let m = mon_at(battle, actor);

    if !m.is_fainted() && m.flags.has(mon_flags::COMMANDING | mon_flags::COMMANDED) {
        return true;
    }


    if !m.is_fainted() && m.volatiles.conds.has(crate::mon::condition_ids::SKYDROPPED) {
        return true;
    }


    if m.is_fainted()
        || (battle.rules().modern_type_immunities && m.types.contains(&Some(engine_data::type_chart::Type::Ghost)))
        || (m.ability == engine_data::abilities_table::ability_ids::RUNAWAY && battle.rules().abilities.run_away_escapes_trapping)
        || m.effective_item() == engine_data::items_table::item_ids::SHEDSHELL
    {
        return false;
    }
    if m.trap_turns > 0 && m.trapped_by != 0 && m.trapped_by != TRAPPER_GONE {
        return true;
    }

    if m.volatiles.has(volatile_flags::INGRAIN) || battle.field.fairy_lock_turns > 0 || trapper_still_out(battle, m.locked_by) {
        return true;
    }

    if m.volatiles.has(volatile_flags::NO_RETREAT) || trapper_still_out(battle, m.octolock_source) {
        return true;
    }

    let steel = m.types.contains(&Some(engine_data::type_chart::Type::Steel));
    let grounded = is_grounded(m);
    (0..2u8).any(|slot| {
        let foe = mon_at(battle, Actor { side: actor.other_side(), slot });
        !foe.is_fainted()
            && match foe.ability {
                engine_data::abilities_table::ability_ids::SHADOWTAG => m.ability != engine_data::abilities_table::ability_ids::SHADOWTAG,
                engine_data::abilities_table::ability_ids::ARENATRAP => grounded,
                engine_data::abilities_table::ability_ids::MAGNETPULL => steel,
                _ => false,
            }
    })
}



const TRAPPER_GONE: u8 = u8::MAX;


const GMAX_TRAP: u8 = 0xF0;
const GMAX_TRAP_BAND: u8 = 0xF1;

fn trapper_code(actor: Actor) -> u8 {
    actor.side * 2 + actor.slot + 1
}


fn trapper_actor(code: u8) -> Actor {
    let c = code - 1;
    Actor { side: c / 2, slot: c % 2 }
}









pub(crate) fn apply_disable(battle: &mut Battle, actor: Actor, during_own_move: bool) -> bool {
    let will_move = !mon_at(battle, actor).volatiles.has(volatile_flags::ACTED_THIS_TURN);
    let mon = mon_at_mut(battle, actor);


    if mon.disable_turns > 0 || mon.last_move == 0 || mon.hp == 0 {
        return false;
    }


    let out_of_pp = mon.moves.iter().zip(mon.pp.iter()).any(|(&m, &pp)| m == mon.last_move && pp == 0);
    if out_of_pp {
        return false;
    }
    mon.disable_move = mon.last_move;
    mon.disable_turns = if will_move || during_own_move { 4 } else { 5 };
    true
}





pub(crate) fn apply_encore(battle: &mut Battle, target: Actor) -> bool {
    let acted = mon_at(battle, target).volatiles.has(volatile_flags::ACTED_THIS_TURN);
    let rules = battle.rules();
    let mon = mon_at_mut(battle, target);


    if mon.encore_turns > 0
        || mon.last_move == 0
        || mon.flags.has(crate::mon::mon_flags::LAST_MOVE_Z)
        || is_dynamaxed(mon)
        || rules.move_data(mon.last_move).call_flags & moves_table::CALL_FAIL_ENCORE != 0
    {
        return false;
    }
    let has_pp = mon.moves.iter().zip(mon.pp.iter()).any(|(&m, &pp)| m == mon.last_move && pp > 0);
    if !has_pp {
        return false;
    }
    mon.encore_move = mon.last_move;

    mon.encore_turns = if acted { 4 } else { 3 };
    true
}



fn is_resist_berry(item: engine_data::items_table::ItemId) -> bool {
    use engine_data::items_table::item_ids::*;
    matches!(
        item,
        BABIRIBERRY | CHARTIBERRY | CHILANBERRY | CHOPLEBERRY | COBABERRY | COLBURBERRY | HABANBERRY | KASIBBERRY | KEBIABERRY
            | OCCABERRY | PASSHOBERRY | PAYAPABERRY | RINDOBERRY | ROSELIBERRY | SHUCABERRY | TANGABERRY | WACANBERRY | YACHEBERRY
    )
}





















fn invulnerable_to_field_move(battle: &Battle, actor: Actor, target: Actor) -> bool {
    let m = mon_at(battle, target);
    target != actor && (m.volatiles.has(volatile_flags::INVULNERABLE) || m.flags.has(mon_flags::COMMANDING)) && !no_guard_in_play(battle, actor, target)
}

fn no_guard_in_play(battle: &Battle, actor: Actor, target: Actor) -> bool {
    let holds = |a: Actor| mon_at(battle, a).ability == engine_data::abilities_table::ability_ids::NOGUARD && !gone_for_damage_pass(mon_at(battle, a));
    let user = mon_at(battle, actor);
    let locked = user.lock_on_turns > 0 && user.lock_on_target == mon_code(battle, target);
    holds(actor) || holds(target) || locked
}

fn gone_for_damage_pass(m: &Mon) -> bool {
    (m.is_fainted() && !m.flags.has(crate::mon::mon_flags::ALIVE_AT_HIT_START)) || m.flags.has(crate::mon::mon_flags::SELF_DESTRUCTING)
}

fn base_power_tie_draws(battle: &Battle, actor: Actor, target: Actor, rng: &mut Rng) {
    use engine_data::abilities_table::ability_ids as ab;
    use engine_data::items_table::item_ids as it;
    let speed_of = |a: Actor| mon_at(battle, a).speed_cache;
    let mut entries: StackVec<(Actor, Action, i8, i64), 32> = StackVec::new();
    let mut push = |a: Actor, priority: i8, speed: i64, sub_order: i64| {
        entries.push((a, Action::Move { move_slot: 0, target_slot: 0, mega: false, z: false }, priority, speed * 16 + (15 - sub_order)));
    };
    let attacker = mon_at(battle, actor);
    let ability_priority = match real_ability(attacker) {

        ab::NORMALIZE if battle.rules().abilities.normalize == crate::rules::Normalize::TypeOnly => None,
        ab::TECHNICIAN => Some(30),
        ab::RIVALRY => Some(24),
        ab::AERILATE | ab::DRAGONIZE | ab::GALVANIZE | ab::IRONFIST | ab::NORMALIZE | ab::PIXILATE | ab::RECKLESS | ab::REFRIGERATE => Some(23),
        ab::ANALYTIC | ab::SANDFORCE | ab::SHEERFORCE | ab::SUPREMEOVERLORD | ab::TOUGHCLAWS => Some(21),
        ab::MEGALAUNCHER | ab::SHARPNESS | ab::STRONGJAW | ab::FLAREBOOST | ab::TOXICBOOST => Some(19),
        ab::PUNKROCK => Some(7),
        _ => None,
    };
    if let Some(pr) = ability_priority {
        push(actor, pr, speed_of(actor), 7);
    }


    if type_boost_item_type(attacker.item).is_some()
        || matches!(
            attacker.item,
            engine_data::items_table::item_ids::ADAMANTORB
                | engine_data::items_table::item_ids::LUSTROUSORB
                | engine_data::items_table::item_ids::GRISEOUSORB
                | engine_data::items_table::item_ids::ADAMANTCRYSTAL
                | engine_data::items_table::item_ids::LUSTROUSGLOBE
                | engine_data::items_table::item_ids::GRISEOUSCORE
                | engine_data::items_table::item_ids::SOULDEW
        )
        || matches!(
            attacker.item,
            engine_data::items_table::item_ids::WELLSPRINGMASK
                | engine_data::items_table::item_ids::HEARTHFLAMEMASK
                | engine_data::items_table::item_ids::CORNERSTONEMASK
        )
    {
        push(actor, 15, speed_of(actor), 8);
    }

    if matches!(attacker.item, it::MUSCLEBAND | it::WISEGLASSES) {
        push(actor, 16, speed_of(actor), 8);
    }
    if attacker.item == it::PUNCHINGGLOVE {
        push(actor, 23, speed_of(actor), 8);
    }
    for a in all_actors() {
        let m = mon_at(battle, a);
        if gone_for_damage_pass(m) {
            continue;
        }
        if matches!(real_ability(m), ab::FAIRYAURA | ab::DARKAURA) {
            push(a, 20, speed_of(a), 7);
        }
        if matches!(real_ability(m), ab::STEELYSPIRIT | ab::POWERSPOT | ab::BATTERY) && a.side == actor.side {
            push(a, 22, speed_of(a), 7);
        }
    }
    if real_ability(mon_at(battle, target)) == ab::DRYSKIN && !gone_for_damage_pass(mon_at(battle, target)) {
        push(target, 17, speed_of(target), 7);
    }
    if battle.rules().abilities.heatproof_halves_base_power && real_ability(mon_at(battle, target)) == ab::HEATPROOF && !gone_for_damage_pass(mon_at(battle, target)) {
        push(target, 18, speed_of(target), 7);
    }

    if mon_at(battle, target).volatiles.has(volatile_flags::INVULNERABLE) && semi_invulnerable_move(mon_at(battle, target)) == moves_table::move_ids::BOUNCE {
        push(target, 0, speed_of(target), 2);
    }

    for a in all_actors() {
        if !mon_at(battle, a).is_fainted() && mon_at(battle, a).volatiles.conds.has(crate::mon::condition_ids::SKYDROP) {
            push(a, 0, speed_of(a), 2);
        }
    }
    let v = attacker.volatiles;
    if v.has(volatile_flags::CHARGE) {
        push(actor, 9, speed_of(actor), 2);
    }
    if v.has(volatile_flags::HELPINGHAND) {
        push(actor, 10, speed_of(actor), 2);
    }
    if v.conds.has(crate::mon::condition_ids::MEFIRST) {
        push(actor, 12, speed_of(actor), 2);
    }
    if v.has(volatile_flags::GEM) {
        push(actor, 14, speed_of(actor), 2);
    }
    if battle.field.terrain != crate::field::Terrain::None {
        push(actor, 6, 0, 5);
    }


    for (bit, turns) in [(1u8, battle.field.mud_sport_turns), (2u8, battle.field.water_sport_turns)] {
        if turns > 0 {
            push(actor, 1, 0, if battle.field.sports_called & bit != 0 { 5 } else { 2 });
        }
    }

    for a in all_actors() {
        let m = mon_at(battle, a);
        if !gone_for_damage_pass(m) {
            let held = m.volatiles.conds.turns(crate::mon::condition_ids::SPORTS).unwrap_or(0);
            for bit in [1u8, 2] {
                if held & bit != 0 {
                    push(a, 1, speed_of(a), 2);
                }
            }
        }
    }
    if entries.len() > 1 {
        speed_sort(&mut entries, rng);
    }
}

fn modify_damage_tie_draws(battle: &Battle, actor: Actor, target: Actor, rng: &mut Rng) {
    use engine_data::abilities_table::ability_ids;
    use engine_data::items_table::item_ids;
    let defender = mon_at(battle, target);
    let attacker = mon_at(battle, actor);



    let speed_of = |m: &Mon| m.speed_cache;
    let defender_speed = speed_of(defender);
    let attacker_speed = speed_of(attacker);

    let mut handlers: StackVec<(i64, u8), 32> = StackVec::new();


    for s in &battle.sides {
        let side = &s.side_conditions;
        for _ in [side.reflect_turns, side.light_screen_turns, side.aurora_veil_turns].iter().filter(|&&t| t > 0) {
            handlers.push((0, 4));
        }
    }


    if matches!(real_ability(defender), ability_ids::FILTER | ability_ids::SOLIDROCK | ability_ids::PRISMARMOR | ability_ids::MULTISCALE | ability_ids::SHADOWSHIELD | ability_ids::AURAGUARD | ability_ids::PUNKROCK | ability_ids::FLUFFY | ability_ids::ICESCALES) {
        handlers.push((defender_speed, 7));
    }
    if matches!(real_ability(attacker), ability_ids::SNIPER | ability_ids::TINTEDLENS | ability_ids::NEUROFORCE) {
        handlers.push((attacker_speed, 7));
    }

    if defender.volatiles.has(volatile_flags::INVULNERABLE)
        && matches!(semi_invulnerable_move(defender), moves_table::move_ids::DIG | moves_table::move_ids::DIVE | moves_table::move_ids::FLY)
    {
        handlers.push((defender_speed, 2));
    }


    for flag in [volatile_flags::GLAIVERUSH, volatile_flags::MINIMIZED] {
        if defender.volatiles.has(flag) {
            handlers.push((defender_speed, 2));
        }
    }



    if defender.flags.has(crate::mon::mon_flags::DYNAMAXED) {
        handlers.push((defender_speed, 2));
    }

    for side in 0..2u8 {
        for slot in 0..2u8 {
            let m = mon_at(battle, Actor { side, slot });
            if !gone_for_damage_pass(m) && real_ability(m) == ability_ids::FRIENDGUARD {
                handlers.push((speed_of(m), 7));
            }
        }
    }

    if is_resist_berry(defender.item) {
        handlers.push((defender_speed, 8));
    }
    if matches!(attacker.item, item_ids::LIFEORB | item_ids::EXPERTBELT) {
        handlers.push((attacker_speed, 8));
    }

    if attacker.volatiles.conds.has(crate::mon::condition_ids::METRONOME) {
        handlers.push((attacker_speed, 2));
    }

    handlers.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    let mut start = 0;
    while start < handlers.len() {
        let key = handlers[start];
        let group = handlers[start..].iter().take_while(|&&h| h == key).count();
        let end = start + group;
        for i in start..end.saturating_sub(1) {
            rng.random_range(i as u32, end as u32);
        }
        start = end;
    }
}



fn knock_off_power_modifier(rules: &crate::rules::Rules, move_id: u16, defender: &Mon) -> Option<(i64, i64)> {
    (move_id == moves_table::move_ids::KNOCKOFF && crate::items::knock_off_boosts(rules, defender)).then_some((3, 2))
}


fn beat_up_allies(battle: &Battle, actor: Actor) -> StackVec<usize, 16> {
    let side = &battle.sides[actor.side as usize];
    let own = side.active[actor.slot as usize] as usize;
    side.order.iter().map(|&i| i as usize).filter(|&i| i == own || (!side.mons[i].is_fainted() && side.mons[i].status == Status::None)).collect()
}


fn beat_up_power(battle: &Battle, actor: Actor, hit_number: u8) -> i64 {
    let allies = beat_up_allies(battle, actor);
    let idx = allies.get(hit_number as usize - 1).copied().unwrap_or(0);


    let mon = &battle.sides[actor.side as usize].mons[idx];
    let current = if mon.flags.has(mon_flags::TRANSFORMED) { mon.pre_transform_species } else { mon.species };
    let data = battle.species_data(current);
    let species = if data.battle_only_base != crate::ids::NONE_ID { data.battle_only_base } else { current };
    5 + (battle.species_data(species).base_stats[1] / 10) as i64
}





fn pledge_kind(move_id: u16) -> u8 {
    match move_id {
        moves_table::move_ids::FIREPLEDGE => 1,
        moves_table::move_ids::GRASSPLEDGE => 2,
        moves_table::move_ids::WATERPLEDGE => 3,
        _ => 0,
    }
}



fn pledge_combo(m: &Mon, move_id: u16) -> Option<(engine_data::type_chart::Type, u8)> {
    use engine_data::type_chart::Type;
    let own = pledge_kind(move_id);
    let first = m.volatiles.conds.turns(crate::mon::condition_ids::PLEDGE)? & 3;
    match (own.min(first), own.max(first)) {
        (1, 2) => Some((Type::Fire, 1)),
        (2, 3) => Some((Type::Grass, 2)),
        (1, 3) => Some((Type::Water, 3)),
        _ => None,
    }
}




fn overflow_secondary_chance(battle: &Battle, chance: u32, effect: &SecondaryEffect) -> u32 {
    if battle.rules().move_effects.secondary_chance_overflow && matches!(effect, SecondaryEffect::Boosts(_) | SecondaryEffect::SelfBoosts(_)) {
        chance % 256
    } else {
        chance
    }
}

fn move_secondary_chance(battle: &Battle, actor: Actor, move_id: u16, chance: u32, flinch: bool) -> u32 {
    let rainbow = battle.sides[actor.side as usize].side_conditions.rainbow_turns > 0
        && move_id != moves_table::move_ids::SECRETPOWER
        && !(flinch && mon_at(battle, actor).ability == engine_data::abilities_table::ability_ids::SERENEGRACE);
    serene_grace_chance(battle, actor, if rainbow { chance * 2 } else { chance })
}


fn ash_greninja(m: &Mon) -> bool {
    m.species == engine_data::species_table::species_ids::GRENINJAASH
        && m.ability == engine_data::abilities_table::ability_ids::BATTLEBOND
        && !m.flags.has(mon_flags::TRANSFORMED)
}

fn base_power_for_move(move_id: u16, move_data: &MoveData, attacker: &Mon, defender: &Mon) -> i64 {
    if pledge_combo(attacker, move_id).is_some() {
        return 150;
    }
    match move_id {


        moves_table::move_ids::HIDDENPOWER if move_data.base_power == 0 => crate::team::hidden_power(attacker.ivs).1 as i64,
        moves_table::move_ids::LOWKICK | moves_table::move_ids::GRASSKNOT => low_kick_base_power(defender),

        moves_table::move_ids::WATERSHURIKEN if ash_greninja(attacker) => move_data.base_power as i64 + 5,

        moves_table::move_ids::TERABLAST if attacker.tera.active && attacker.tera.tera_type == Some(engine_data::type_chart::Type::Stellar) => 100,

        moves_table::move_ids::HEAVYSLAM | moves_table::move_ids::HEATCRASH => {
            let weight = |m: &Mon| float_stone_weight(ability_weight_hg(base_weight_hg(m), m.ability), m);
            let (mine, theirs) = (weight(attacker), weight(defender));
            match () {
                _ if mine >= theirs * 5 => 120,
                _ if mine >= theirs * 4 => 100,
                _ if mine >= theirs * 3 => 80,
                _ if mine >= theirs * 2 => 60,
                _ => 40,
            }
        }

        moves_table::move_ids::ACROBATICS if attacker.item == crate::ids::NONE_ID => move_data.base_power as i64 * 2,

        moves_table::move_ids::HEX if defender.status != Status::None || defender.ability == engine_data::abilities_table::ability_ids::COMATOSE => move_data.base_power as i64 * 2,

        moves_table::move_ids::ERUPTION | moves_table::move_ids::WATERSPOUT | moves_table::move_ids::DRAGONENERGY => eruption_base_power(attacker),

        moves_table::move_ids::ROUND if attacker.volatiles.has(volatile_flags::ROUND_UP) => move_data.base_power as i64 * 2,

        moves_table::move_ids::RAGEFIST => (50 + 50 * attacker.times_attacked as i64).min(350),

        moves_table::move_ids::SPITUP => 100 * attacker.stockpile_layers as i64,

        moves_table::move_ids::ROLLOUT | moves_table::move_ids::ICEBALL => {
            let hits = attacker.volatiles.conds.turns(crate::mon::condition_ids::ROLLOUT).map_or(0, |v| v & 7);
            let curl = if attacker.volatiles.conds.has(crate::mon::condition_ids::DEFENSECURL) { 2 } else { 1 };
            (30i64 << hits) * curl
        }

        moves_table::move_ids::ASSURANCE if defender.volatiles.has(volatile_flags::HURT_THIS_TURN) => move_data.base_power as i64 * 2,


        moves_table::move_ids::POWERTRIP | moves_table::move_ids::STOREDPOWER => 20 + 20 * attacker.boosts.iter().map(|&b| b.max(0) as i64).sum::<i64>(),

        moves_table::move_ids::INFERNALPARADE if defender.status != Status::None || defender.ability == engine_data::abilities_table::ability_ids::COMATOSE => move_data.base_power as i64 * 2,

        moves_table::move_ids::FLAIL | moves_table::move_ids::REVERSAL => {
            let ratio = (attacker.hp as i64 * 48 / attacker.max_hp.max(1) as i64).max(1);
            match ratio {
                r if r < 2 => 200,
                r if r < 5 => 150,
                r if r < 10 => 100,
                r if r < 17 => 80,
                r if r < 33 => 40,
                _ => 20,
            }
        }

        moves_table::move_ids::HARDPRESS => {
            let frac = defender.hp as i64 * 4096 / defender.max_hp.max(1) as i64;
            ((100 * (100 * frac) + 2048 - 1) / 4096 / 100).max(1)
        }


        moves_table::move_ids::RETURN => (attacker.happiness as i64 * 10 / 25).max(1),
        moves_table::move_ids::FRUSTRATION => ((255 - attacker.happiness as i64) * 10 / 25).max(1),

        moves_table::move_ids::TRUMPCARD => match attacker.moves.iter().position(|&m| m == moves_table::move_ids::TRUMPCARD).map(|i| attacker.pp[i]) {
            Some(0) => 200,
            Some(1) => 80,
            Some(2) => 60,
            Some(3) => 50,
            _ => 40,
        },

        moves_table::move_ids::CRUSHGRIP | moves_table::move_ids::WRINGOUT => {
            let frac = defender.hp as i64 * 4096 / defender.max_hp.max(1) as i64;
            ((120 * (100 * frac) + 2048 - 1) / 4096 / 100).max(1)
        }

        moves_table::move_ids::PUNISHMENT => (60 + 20 * defender.boosts.iter().map(|&b| b.max(0) as i64).sum::<i64>()).min(200),

        moves_table::move_ids::SMELLINGSALTS if defender.status == Status::Paralysis => move_data.base_power as i64 * 2,
        moves_table::move_ids::WAKEUPSLAP if defender.status == Status::Sleep || defender.ability == engine_data::abilities_table::ability_ids::COMATOSE => move_data.base_power as i64 * 2,

        moves_table::move_ids::STOMPINGTANTRUM | moves_table::move_ids::TEMPERFLARE if attacker.move_result_last_turn == crate::mon::move_result::FAILED => move_data.base_power as i64 * 2,
        _ => move_data.base_power as i64,
    }
}




fn low_kick_base_power(defender: &Mon) -> i64 {
    low_kick_bp_for_weight(float_stone_weight(ability_weight_hg(base_weight_hg(defender), defender.ability), defender))
}



fn low_kick_bp_for_weight(weight_hg: i64) -> i64 {
    match weight_hg {
        w if w >= 2000 => 120,
        w if w >= 1000 => 100,
        w if w >= 500 => 80,
        w if w >= 250 => 60,
        w if w >= 100 => 40,
        _ => 20,
    }
}









fn type_locked_species(m: &Mon) -> bool {
    use engine_data::species_table::species_ids::{ARCEUS, ARCEUSWATER, SILVALLY, SILVALLYWATER};
    (ARCEUS..=ARCEUSWATER).contains(&m.species) || (SILVALLY..=SILVALLYWATER).contains(&m.species) || m.tera.active
}


fn base_weight_hg(m: &Mon) -> i64 {
    let w = engine_data::species_table::get(m.species).weight_hg as i64;
    let cuts = m.volatiles.conds.turns(crate::mon::condition_ids::AUTOTOMIZE).unwrap_or(0) as i64;
    if cuts == 0 { w } else { (w - 1000 * cuts).max(1) }
}

fn float_stone_weight(weight_hg: i64, m: &Mon) -> i64 {
    if m.effective_item() == engine_data::items_table::item_ids::FLOATSTONE { weight_hg / 2 } else { weight_hg }
}

fn ability_weight_hg(weight_hg: i64, ability: engine_data::abilities_table::AbilityId) -> i64 {
    use engine_data::abilities_table::ability_ids;
    match ability {
        ability_ids::HEAVYMETAL => weight_hg * 2,
        ability_ids::LIGHTMETAL => weight_hg / 2,
        _ => weight_hg,
    }
}



fn eruption_base_power(attacker: &Mon) -> i64 {
    (150 * attacker.hp as i64 / attacker.max_hp as i64).max(1)
}




fn ate_ability_base_power_modifier(battle: &Battle, ate_type: Option<engine_data::type_chart::Type>) -> Option<(i64, i64)> {
    let (n, d) = battle.rules().abilities.ate_modifier;
    ate_type.map(|_| (n as i64, d as i64))
}




fn helping_hand_modifier(attacker: &Mon) -> Option<(i64, i64)> {
    if !attacker.volatiles.has(volatile_flags::HELPINGHAND) {
        return None;
    }
    let restarts = attacker.volatiles.conds.turns(crate::mon::condition_ids::HELPINGHAND_RESTARTS).unwrap_or(0) as u32;
    Some((3i64.pow(1 + restarts), 2i64.pow(1 + restarts)))
}










fn expanding_force_modifier(field: &crate::field::Field, move_id: u16, attacker: &Mon) -> Option<(i64, i64)> {
    (move_id == moves_table::move_ids::EXPANDINGFORCE && field.terrain == crate::field::Terrain::Psychic && is_grounded(attacker))
        .then_some((3, 2))
}





fn flash_fire_attack_modifier(flash_fire_active: bool, move_type: engine_data::type_chart::Type) -> Option<(i64, i64)> {
    (flash_fire_active && move_type == engine_data::type_chart::Type::Fire).then_some((3, 2))
}



fn iron_fist_base_power_modifier(ability: engine_data::abilities_table::AbilityId, punch: bool) -> Option<(i64, i64)> {
    (ability == engine_data::abilities_table::ability_ids::IRONFIST && punch).then_some((4915, 4096))
}



fn cant_use_twice(move_id: u16) -> bool {
    matches!(move_id, moves_table::move_ids::GIGATONHAMMER | moves_table::move_ids::BLOODMOON)
}

fn is_crash_move(move_id: u16) -> bool {
    matches!(move_id, moves_table::move_ids::AXEKICK | moves_table::move_ids::HIGHJUMPKICK | moves_table::move_ids::SUPERCELLSLAM | moves_table::move_ids::JUMPKICK)
}


fn supreme_overlord_modifier(attacker: &Mon) -> Option<(i64, i64)> {
    let fallen = (attacker.flags.0 & crate::mon::mon_flags::FALLEN_MASK) >> crate::mon::mon_flags::FALLEN_SHIFT;
    (attacker.ability == engine_data::abilities_table::ability_ids::SUPREMEOVERLORD && fallen > 0)
        .then(|| ([4096, 4506, 4915, 5325, 5734, 6144][fallen as usize], 4096))
}


fn big_root(m: &Mon, amount: u16) -> u16 {
    if m.effective_item() == engine_data::items_table::item_ids::BIGROOT { damage::modify(amount as i64, 5324, 4096) as u16 } else { amount }
}


fn sharpness_base_power_modifier(ability: engine_data::abilities_table::AbilityId, slicing: bool) -> Option<(i64, i64)> {
    (ability == engine_data::abilities_table::ability_ids::SHARPNESS && slicing).then_some((3, 2))
}








fn resist_berry_modifier(
    item: engine_data::items_table::ItemId,
    move_type: engine_data::type_chart::Type,
    effectiveness: Effectiveness,
) -> Option<(i64, i64)> {
    use engine_data::items_table::item_ids;
    use engine_data::type_chart::Type;

    if item == item_ids::CHILANBERRY && move_type == Type::Normal {
        return Some((1, 2));
    }
    if !matches!(effectiveness, Effectiveness::Normal(stage) if stage > 0) {
        return None;
    }
    match (item, move_type) {
        (item_ids::CHOPLEBERRY, Type::Fighting) => Some((1, 2)),
        (item_ids::CHARTIBERRY, Type::Rock) => Some((1, 2)),
        (item_ids::KEBIABERRY, Type::Poison) => Some((1, 2)),
        (item_ids::PAYAPABERRY, Type::Psychic) => Some((1, 2)),
        (item_ids::SHUCABERRY, Type::Ground) => Some((1, 2)),
        (item_ids::WACANBERRY, Type::Electric) => Some((1, 2)),
        (item_ids::YACHEBERRY, Type::Ice) => Some((1, 2)),
        (item_ids::OCCABERRY, Type::Fire) => Some((1, 2)),
        (item_ids::COLBURBERRY, Type::Dark) => Some((1, 2)),


        (item_ids::PASSHOBERRY, Type::Water) => Some((1, 2)),
        (item_ids::ROSELIBERRY, Type::Fairy) => Some((1, 2)),
        (item_ids::HABANBERRY, Type::Dragon) => Some((1, 2)),
        (item_ids::KASIBBERRY, Type::Ghost) => Some((1, 2)),
        (item_ids::COBABERRY, Type::Flying) => Some((1, 2)),
        (item_ids::RINDOBERRY, Type::Grass) => Some((1, 2)),
        (item_ids::BABIRIBERRY, Type::Steel) => Some((1, 2)),
        (item_ids::TANGABERRY, Type::Bug) => Some((1, 2)),
        _ => None,
    }
}





fn filter_modifier(ability: engine_data::abilities_table::AbilityId, effectiveness: Effectiveness, sound: bool, full_hp: bool) -> Option<(i64, i64)> {
    use engine_data::abilities_table::ability_ids;


    if matches!(ability, ability_ids::MULTISCALE | ability_ids::SHADOWSHIELD) {
        return if full_hp { Some((1, 2)) } else { None };
    }



    if ability == ability_ids::PUNKROCK && sound {
        return Some((1, 2));
    }
    if !matches!(effectiveness, Effectiveness::Normal(stage) if stage > 0) {
        return None;
    }
    match ability {

        ability_ids::FILTER | ability_ids::SOLIDROCK | ability_ids::PRISMARMOR => Some((3, 4)),
        _ => None,
    }
}




fn attacker_move_ability_power_modifier(
    ability: engine_data::abilities_table::AbilityId,
    move_data: &MoveData,
    move_type: engine_data::type_chart::Type,
    weather: crate::field::Weather,
    sheer_force: bool,
) -> Option<(i64, i64)> {
    use engine_data::abilities_table::ability_ids;
    use engine_data::type_chart::Type;
    match ability {

        ability_ids::STRONGJAW if move_data.bite => Some((3, 2)),

        ability_ids::SANDFORCE if weather == crate::field::Weather::Sand && matches!(move_type, Type::Rock | Type::Ground | Type::Steel) => Some((5325, 4096)),

        ability_ids::SHEERFORCE if sheer_force => Some((5325, 4096)),
        ability_ids::TOUGHCLAWS if move_data.contact => Some((5325, 4096)),
        ability_ids::PUNKROCK if move_data.sound => Some((5325, 4096)),
        _ => None,
    }
}







fn aura_power_modifier(battle: &Battle, actor: Actor, target: Actor, move_type: engine_data::type_chart::Type, category: Category) -> Option<(i64, i64)> {
    use engine_data::abilities_table::{ability_flags, ability_ids};
    use engine_data::type_chart::Type;
    let aura = match move_type {
        Type::Fairy => ability_ids::FAIRYAURA,
        Type::Dark => ability_ids::DARKAURA,
        _ => return None,
    };
    if target == actor || category == Category::Status {
        return None;
    }
    let breaker = breaks_molds_mon(mon_at(battle, actor));
    let holds = |ability: engine_data::abilities_table::AbilityId| {
        all_actors().into_iter().any(|a| {
            let m = mon_at(battle, a);
            !gone_for_damage_pass(m)
                && m.ability == ability
                && !(breaker && a != actor && !has_ability_shield(m) && battle.rules().ability_has_flag(ability, ability_flags::BREAKABLE))
        })
    };
    if !holds(aura) {
        return None;
    }
    Some(if holds(ability_ids::AURABREAK) { (3072, 4096) } else { (5448, 4096) })
}



fn ally_base_power(battle: &Battle, actor: Actor, ability: engine_data::abilities_table::AbilityId) -> Option<(i64, i64)> {
    let holders = (0..2u8)
        .map(|slot| Actor { side: actor.side, slot })
        .filter(|&a| a != actor && !gone_for_damage_pass(mon_at(battle, a)) && mon_at(battle, a).ability == ability)
        .count();
    match holders {
        1 => Some((5325, 4096)),
        2 => Some((5325 * 5325 / 4096 + if (5325 * 5325) % 4096 >= 2048 { 1 } else { 0 }, 4096)),
        _ => None,
    }
}




fn liquid_voice_type(ability: engine_data::abilities_table::AbilityId, sound: bool) -> Option<engine_data::type_chart::Type> {
    use engine_data::abilities_table::ability_ids;
    (ability == ability_ids::LIQUIDVOICE && sound).then_some(engine_data::type_chart::Type::Water)
}









