    #[test]
    fn parting_shot_lowers_the_target_and_queues_a_self_switch() {
        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::PARTINGSHOT));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        battle.sides[0].mons[2] = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[1].mons[0].boosts[Stat::Atk as usize], -1, "Parting Shot should lower the target's Atk");
        assert_eq!(battle.sides[1].mons[0].boosts[Stat::SpA as usize], -1, "and SpA");
        let actor = Actor { side: 0, slot: 0 };
        assert!(mon_at(&battle, actor).volatiles.has(volatile_flags::VOLUNTARY_SWITCH), "a successful debuff should queue the user's own switch-out");
    }

