    #[test]
    fn wide_guard_blocks_a_spread_move_into_its_side_but_not_a_single_target_one() {
        let attacker = test_mon([Some(Type::Ground), None], [100, 100, 100, 100, 100], moves_with(move_ids::EARTHQUAKE));
        let partner = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let guard_user = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::WIDEGUARD));
        let foe_partner = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle = test_battle([attacker, partner], [guard_user, foe_partner], 1);

        step(&mut battle, [[mv(0, 0), no_move()], [mv(0, 0), no_move()]]);
        assert!(battle.sides[1].side_conditions.wide_guard, "Wide Guard should set its side flag");
        assert_eq!(battle.sides[1].mons[0].hp, 200, "Earthquake should not hit the guard user");
        assert_eq!(battle.sides[1].mons[1].hp, 200, "...or its partner, while Wide Guard is up");
        assert!(battle.sides[0].mons[1].hp < 200, "Earthquake's own ally hit is on the attacker's side and is unaffected");
        assert_eq!(battle.sides[1].mons[0].protect_counter, 3, "Wide Guard chains the stall streak from a fresh 0 to 3");
    }

