        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], {
            let mut m = moves_with(move_ids::PROTECT);
            m[1] = move_ids::KINGSSHIELD;
            m
        });
        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 1], moves_with(move_ids::TACKLE));
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        step(&mut battle, [[mv(0, 0), no_move()], [mv(0, 0), no_move()]]);
