    #[test]
    fn cursed_body_only_disables_on_a_successful_roll_and_only_when_not_already_disabled() {
        use engine_data::abilities_table::ability_ids;


        let passing = (1..10_000u64).find(|&s| Rng::new(s).chance(3, 10)).unwrap();
        let failing = (1..10_000u64).find(|&s| !Rng::new(s).chance(3, 10)).unwrap();
        for (seed, should_disable) in [(passing, true), (failing, false)] {
            let mut attacker = test_mon([Some(Type::Normal), None], [100; 5], moves_with(move_ids::TACKLE));
            attacker.last_move = move_ids::TACKLE;
            let mut holder = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
            holder.ability = ability_ids::CURSEDBODY;
            let mut battle = test_battle(
                [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                [holder, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                1,
            );
            let mut rng = Rng::new(seed);
            crate::abilities::on_damaging_hit(&mut battle, Actor { side: 1, slot: 0 }, Actor { side: 0, slot: 0 }, Type::Normal, Category::Physical, false, false, &mut rng);
            assert_eq!(battle.sides[0].mons[0].disable_turns > 0, should_disable, "seed {seed}");
        }
    }

    #[test]
    fn unnerve_on_a_foe_stops_sitrus_berry_from_being_eaten() {
        use engine_data::abilities_table::ability_ids;
        let holder_with_berry = || {
            let mut m = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
            m.item = engine_data::items_table::item_ids::SITRUSBERRY;
            m
        };
        let plain = || test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let mut unnerved_foe = plain();
        unnerved_foe.ability = ability_ids::UNNERVE;
        unnerved_foe.flags.set(crate::mon::mon_flags::UNNERVED);


        let mut battle = test_battle([holder_with_berry(), plain()], [unnerved_foe, plain()], 1);
        apply_damage_at(&mut battle, Actor { side: 0, slot: 0 }, 150);
        let holder = &battle.sides[0].mons[0];
        assert_eq!(holder.item, engine_data::items_table::item_ids::SITRUSBERRY, "the berry should stay in hand");
        assert_eq!(holder.hp, 50, "and the holder should take the hit with no heal");


        let mut battle = test_battle([holder_with_berry(), plain()], [plain(), plain()], 1);
        apply_damage_at(&mut battle, Actor { side: 0, slot: 0 }, 150);
        let holder = &battle.sides[0].mons[0];
        assert_eq!(holder.item, crate::ids::NONE_ID, "without Unnerve the berry is eaten");
        assert_eq!(holder.hp, 100, "50 left, plus 200/4 from the berry");
    }

    #[test]
    fn unnerve_only_counts_from_an_active_non_fainted_foe() {
        use engine_data::abilities_table::ability_ids;
        let mut unnerved = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        unnerved.ability = ability_ids::UNNERVE;
        unnerved.flags.set(crate::mon::mon_flags::UNNERVED);

        let mut battle = test_battle(
            [test_mon([Some(Type::Normal), None], [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [100; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [100; 5], [0; 4])],
            1,
        );
        battle.sides[1].mons[2] = unnerved;
        assert!(!crate::items::foe_has_unnerve(&battle, Actor { side: 0, slot: 0 }), "a benched Unnerve doesn't count");
        battle.sides[1].mons[0].ability = ability_ids::UNNERVE;
        battle.sides[1].mons[0].flags.set(crate::mon::mon_flags::UNNERVED);
        assert!(crate::items::foe_has_unnerve(&battle, Actor { side: 0, slot: 0 }), "an active one does");
        battle.sides[1].mons[0].flags.set(mon_flags::FAINTED);
        assert!(!crate::items::foe_has_unnerve(&battle, Actor { side: 0, slot: 0 }), "a fainted one doesn't");
    }

