    #[test]
    fn accuracy_stages_scale_accuracy_by_their_difference_truncated_like_showdown() {
        assert_eq!(stage_adjusted_accuracy(100, 0, 0), 100, "neutral stages change nothing");
        assert_eq!(stage_adjusted_accuracy(100, 1, 0), 133, "+1 is trunc(100*4/3)");
        assert_eq!(stage_adjusted_accuracy(100, -1, 0), 75, "-1 is trunc(100*3/4)");
        assert_eq!(stage_adjusted_accuracy(100, 6, 0), 300, "+6 is 3x");
        assert_eq!(stage_adjusted_accuracy(100, 0, 2), 60, "evasion counts against accuracy: 0 - 2 = -2, trunc(100*3/5)");
        assert_eq!(stage_adjusted_accuracy(100, 6, -6), 300, "the difference clamps to +6 before scaling");
        assert_eq!(stage_adjusted_accuracy(90, 2, 2), 90, "equal stages cancel");
    }

