    #[test]
    fn fire_spin_traps_its_target_and_takes_an_eighth_each_residual() {
        let attacker = test_mon([Some(Type::Fire), None], [100; 5], moves_with(move_ids::FIRESPIN));
        let defender = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );

        battle.rng = Rng::new(2);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let trapped = &battle.sides[1].mons[0];
        assert!((4..=5).contains(&trapped.trap_turns), "random(5,7) turns, less the residual that just ticked");
        assert_eq!(trapped.trapped_by, trapper_code(Actor { side: 0, slot: 0 }), "the trap belongs to the attacker");

        let hp_before = battle.sides[1].mons[0].hp;
        step(&mut battle, [[no_move(), no_move()], [no_move(), no_move()]]);
        assert_eq!(hp_before - battle.sides[1].mons[0].hp, 25, "1/8 of 200 max HP per residual");
    }

