    #[test]
    fn sun_blocks_freeze_but_not_other_statuses() {
        let mut battle = test_battle(
            [test_mon([Some(Type::Normal), None], [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [100; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [100; 5], [0; 4])],
            1,
        );
        let target = Actor { side: 1, slot: 0 };
        battle.field.weather = crate::field::Weather::Sun;
        { let mut r = battle.rng; try_set_status(&mut battle, Actor { side: 0, slot: 0 }, target, Status::Freeze, &mut r); battle.rng = r; }
        assert_eq!(mon_at(&battle, target).status, Status::None, "Sunny Day's onImmunity blocks freeze");
        { let mut r = battle.rng; try_set_status(&mut battle, Actor { side: 0, slot: 0 }, target, Status::Burn, &mut r); battle.rng = r; }
        assert_eq!(mon_at(&battle, target).status, Status::Burn, "other statuses still land in sun");
    }

