    fn weather_ball_becomes_water_type_and_doubles_power_in_rain() {



        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 1], moves_with(move_ids::WEATHERBALL));
        let defender = test_mon([Some(Type::Fire), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut rain_battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        rain_battle.field.weather = crate::field::Weather::Rain;
        let clear_attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 1], moves_with(move_ids::WEATHERBALL));
        let clear_defender = test_mon([Some(Type::Fire), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut clear_battle = test_battle(
            [clear_attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [clear_defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        step(&mut rain_battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        step(&mut clear_battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);



        let rain_damage = 200 - rain_battle.sides[1].mons[0].hp;
        let clear_damage = 200 - clear_battle.sides[1].mons[0].hp;
        assert!(rain_damage > clear_damage * 3, "Weather Ball under Rain (Water-type, 2x power, super effective vs Fire) should deal far more than its clear-weather (Normal-type, neutral, base power) hit");
    }

    #[test]
    fn dire_claw_inflicts_one_of_three_statuses_at_roughly_thirty_percent_rate() {




        let (mut poisoned, mut paralyzed, mut slept, mut none) = (0, 0, 0, 0);
        let trials = 3000;
        for seed in 0..trials {
            let attacker = test_mon([Some(Type::Poison), None], [100, 100, 100, 100, 1], moves_with(move_ids::DIRECLAW));
            let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
            let mut battle = test_battle(
                [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                seed,
            );
            step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
            match battle.sides[1].mons[0].status {
                Status::Poison => poisoned += 1,
                Status::Paralysis => paralyzed += 1,
                Status::Sleep => slept += 1,
                Status::None => none += 1,
                other => panic!("Dire Claw should never inflict {other:?}"),
            }
        }
        let rate = |n: i32| n as f64 / trials as f64;
        assert!((0.24..=0.37).contains(&rate(poisoned + paralyzed + slept)), "overall secondary rate should be close to 30%");
        for (name, n) in [("poison", poisoned), ("paralysis", paralyzed), ("sleep", slept)] {
            assert!((0.06..=0.15).contains(&rate(n)), "{name} rate {} should be close to 10%", rate(n));
        }
        assert!(none > 0, "should sometimes not trigger at all");
    }

