    #[test]
    fn losing_every_mon_ends_the_battle() {
        let attacker = test_mon([Some(Type::Normal), None], [255, 100, 100, 100, 100], moves_with(move_ids::TACKLE));
        let mut last_mon = test_mon([Some(Type::Normal), None], [100, 1, 100, 100, 100], [0; 4]);
        last_mon.hp = 1;
        let mut dead_partner = test_mon([Some(Type::Normal), None], [1; 5], [0; 4]);
        dead_partner.hp = 0;
        dead_partner.flags.set(mon_flags::FAINTED);
        let mut battle = test_battle([attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [last_mon, dead_partner], 1);

        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.pending, Pending::Over { winner: Some(0) });
    }

    #[test]
    fn rain_boosts_water_and_suppresses_fire() {
        let attacker = test_mon([Some(Type::Fire), None], [100, 100, 100, 100, 100], moves_with(move_ids::FLAREBLITZ));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        battle.field.weather = crate::field::Weather::Rain;
        battle.field.weather_turns = 5;
        let hp_before = battle.sides[1].mons[0].hp;
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let rain_damage = hp_before - battle.sides[1].mons[0].hp;


        let attacker2 = test_mon([Some(Type::Fire), None], [100, 100, 100, 100, 100], moves_with(move_ids::FLAREBLITZ));
        let defender2 = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle2 = test_battle(
            [attacker2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let hp_before2 = battle2.sides[1].mons[0].hp;
        step(&mut battle2, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let no_weather_damage = hp_before2 - battle2.sides[1].mons[0].hp;

        assert!(rain_damage < no_weather_damage, "Rain should suppress Flare Blitz's Fire damage: {rain_damage} vs {no_weather_damage}");
    }

