    #[test]
    fn reflect_reduces_physical_damage_in_doubles() {
        let attacker = test_mon([Some(Type::Fighting), None], [100, 100, 100, 100, 100], moves_with(move_ids::CLOSECOMBAT));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut with_reflect = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        with_reflect.sides[1].side_conditions.reflect_turns = 5;
        let hp_before = with_reflect.sides[1].mons[0].hp;
        step(&mut with_reflect, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let reflected_damage = hp_before - with_reflect.sides[1].mons[0].hp;

        let attacker2 = test_mon([Some(Type::Fighting), None], [100, 100, 100, 100, 100], moves_with(move_ids::CLOSECOMBAT));
        let defender2 = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut without_reflect = test_battle(
            [attacker2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let hp_before2 = without_reflect.sides[1].mons[0].hp;
        step(&mut without_reflect, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let normal_damage = hp_before2 - without_reflect.sides[1].mons[0].hp;

        assert!(reflected_damage < normal_damage, "Reflect should reduce physical damage: {reflected_damage} vs {normal_damage}");
    }

