    #[test]
    fn hazards_run_in_the_order_they_were_set() {


        for (spikes_first, poisoned) in [(true, true), (false, false)] {
            let mut battle = test_battle(
                [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                1,
            );
            let side = 0;
            if spikes_first {
                add_toxic_spikes(&mut battle, side);
                set_stealth_rock(&mut battle, side);
            } else {
                set_stealth_rock(&mut battle, side);
                add_toxic_spikes(&mut battle, side);
            }
            let mut incoming = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
            incoming.hp = 10;
            battle.sides[0].mons[2] = incoming;
            step(&mut battle, [[switch_to(2), no_move()], [no_move(), no_move()]]);
            let m = &battle.sides[0].mons[2];
            assert_eq!(m.hp, 0, "the rocks knock it out");
            assert_eq!(m.status == Status::Poison, poisoned, "Toxic Spikes first: {spikes_first}");
        }
    }

    #[test]
    fn spikes_layers_increase_damage_and_cap_at_three() {
        let mut battle = test_battle(
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        battle.sides[0].side_conditions.spikes = 2;
        battle.sides[0].mons[2] = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        step(&mut battle, [[switch_to(2), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[0].mons[2].hp, 200 - 200 / 6);


        let mut capped = test_battle(
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        capped.sides[0].side_conditions.spikes = 3;
        let user = test_mon([Some(Type::Ground), None], [100; 5], moves_with(move_ids::SPIKES));
        capped.sides[1].mons[0] = user;
        step(&mut capped, [[no_move(), no_move()], [mv(0, 0), no_move()]]);
        assert_eq!(capped.sides[0].side_conditions.spikes, 3, "Spikes shouldn't exceed 3 layers");
    }

