    #[test]
    fn step_with_hits_reports_a_connecting_damaging_hit() {
        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::TACKLE));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::TACKLE));
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let hits = step_with_hits(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let hit = hits.into_iter().flatten().next().expect("Tackle should have produced one HitRecord");
        assert_eq!(hit.attacker, Actor { side: 0, slot: 0 });
        assert_eq!(hit.target, Actor { side: 1, slot: 0 });
        assert_eq!(hit.move_id, move_ids::TACKLE);



        assert!(damage::possible_damages(&hit.inputs).contains(&hit.damage_dealt));
        assert_eq!(hits.into_iter().flatten().count(), 1, "only one hit happened this turn");
    }

    #[test]
    fn step_with_hits_reports_nothing_for_a_missed_or_status_move() {
        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::SWORDSDANCE));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let hits = step_with_hits(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert!(hits.into_iter().all(|h| h.is_none()), "a Status move shouldn't produce a HitRecord");
    }



    #[test]
    fn electric_terrain_boosts_electric_type_moves_for_grounded_attacker() {
        let attacker = test_mon([Some(Type::Electric), None], [100, 100, 100, 100, 100], moves_with(move_ids::THUNDERBOLT));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut with_terrain = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        with_terrain.field.terrain = crate::field::Terrain::Electric;
        with_terrain.field.terrain_turns = 5;
        let hp_before = with_terrain.sides[1].mons[0].hp;
        step(&mut with_terrain, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let boosted_damage = hp_before - with_terrain.sides[1].mons[0].hp;

        let attacker2 = test_mon([Some(Type::Electric), None], [100, 100, 100, 100, 100], moves_with(move_ids::THUNDERBOLT));
        let defender2 = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut no_terrain = test_battle(
            [attacker2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let hp_before2 = no_terrain.sides[1].mons[0].hp;
        step(&mut no_terrain, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let plain_damage = hp_before2 - no_terrain.sides[1].mons[0].hp;

        assert!(boosted_damage > plain_damage, "Electric Terrain should boost Thunderbolt: {boosted_damage} vs {plain_damage}");
    }




    fn try_set_status_under_terrain(defender_types: [Option<Type>; 2], status: Status, terrain: crate::field::Terrain) -> Status {
        let mut battle = test_battle(
            [test_mon(defender_types, [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        battle.field.terrain = terrain;
        let target = Actor { side: 0, slot: 0 };
        { let mut r = battle.rng; try_set_status(&mut battle, target, target, status, &mut r); battle.rng = r; }
        mon_at(&battle, target).status
    }

    #[test]
    fn electric_terrain_prevents_sleep_on_a_grounded_mon() {
        let status = try_set_status_under_terrain([Some(Type::Normal), None], Status::Sleep, crate::field::Terrain::Electric);
        assert_eq!(status, Status::None, "Electric Terrain should block Sleep on a grounded mon");
    }

    #[test]
    fn electric_terrain_does_not_prevent_other_statuses() {
        let status = try_set_status_under_terrain([Some(Type::Normal), None], Status::Burn, crate::field::Terrain::Electric);
        assert_eq!(status, Status::Burn, "Electric Terrain only blocks Sleep, not every status");
    }

