    fn misty_terrain_blocks_any_major_status_on_a_grounded_mon() {
        let status = try_set_status_under_terrain([Some(Type::Normal), None], Status::Burn, crate::field::Terrain::Misty);
        assert_eq!(status, Status::None, "Misty Terrain blocks any major status, not just Sleep");
    }

