    fn misty_terrain_does_not_protect_an_airborne_mon() {
        let status = try_set_status_under_terrain([Some(Type::Flying), None], Status::Burn, crate::field::Terrain::Misty);
        assert_eq!(status, Status::Burn, "Misty Terrain only protects grounded mons");
    }

