    #[test]
    fn mega_evolution_updates_species_types_stats_and_ability() {
        use engine_data::items_table::item_ids;
        use engine_data::species_table::species_ids;

        let mega_mon = mega_capable_mon(species_ids::CHARIZARD, item_ids::CHARIZARDITEX, moves_with(move_ids::TACKLE));
        let mut battle = test_battle(
            [mega_mon, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        step(&mut battle, [[mv_mega(0, 0), no_move()], [no_move(), no_move()]]);

        let mon = &battle.sides[0].mons[0];
        assert_eq!(mon.species, species_ids::CHARIZARDMEGAX);
        assert_eq!(mon.types, [Some(Type::Fire), Some(Type::Dragon), None], "Mega X changes Charizard's 2nd type Flying -> Dragon");
        assert_eq!(mon.ability, engine_data::abilities_table::ability_ids::TOUGHCLAWS);

        assert_eq!(mon.stats[Stat::Atk as usize], 150);
        assert!(mon.mega.active);
        assert_eq!(mon.mega.base_species, species_ids::CHARIZARD, "should remember the pre-Mega species");
        assert!(battle.sides[0].mega_used);
    }

