    #[test]
    fn chople_berry_halves_a_super_effective_fighting_hit_and_is_consumed() {
        use engine_data::items_table::item_ids;

        let attacker = test_mon([Some(Type::Fighting), None], [100, 100, 100, 100, 100], moves_with(move_ids::CLOSECOMBAT));


        let mut defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        defender.item = item_ids::CHOPLEBERRY;
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let hp_before = battle.sides[1].mons[0].hp;
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let with_berry_damage = hp_before - battle.sides[1].mons[0].hp;
        assert_eq!(battle.sides[1].mons[0].item, crate::ids::NONE_ID, "berry is consumed");

        let attacker2 = test_mon([Some(Type::Fighting), None], [100, 100, 100, 100, 100], moves_with(move_ids::CLOSECOMBAT));
        let defender2 = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut baseline = test_battle(
            [attacker2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender2, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let hp_before2 = baseline.sides[1].mons[0].hp;
        step(&mut baseline, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let baseline_damage = hp_before2 - baseline.sides[1].mons[0].hp;

        assert!(with_berry_damage < baseline_damage, "Chople Berry should roughly halve the damage: {with_berry_damage} vs {baseline_damage}");
    }

