    #[test]
    fn turns_active_increments_once_per_turn_for_an_active_non_fainted_mon() {
        let mut battle = test_battle(
            [test_mon([Some(Type::Normal), None], [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        step(&mut battle, [[no_move(), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[0].mons[0].turns_active, 2, "a lead starts at 1 (it already went through the start-of-battle endTurn) and bumps once after the first turn");
        step(&mut battle, [[no_move(), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[0].mons[0].turns_active, 3, "and again after the second");
    }

    #[test]
    fn switching_in_resets_turns_active_and_move_actions() {
        let outgoing = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let mut bench = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);


        bench.turns_active = 5;
        bench.move_actions_since_switch_in = 3;
        let mut battle = test_battle(
            [outgoing, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        battle.sides[0].mons[2] = bench;
        step(&mut battle, [[switch_to(2), no_move()], [no_move(), no_move()]]);



        assert_eq!(battle.sides[0].mons[2].turns_active, 1, "reset to 0, then this turn's own increment bumps it to 1");
        assert_eq!(battle.sides[0].mons[2].move_actions_since_switch_in, 0, "a switch isn't a move action, so this stays at its reset value");
    }

