    #[test]
    fn fake_out_works_again_after_switching_out_and_back_in() {
        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::FAKEOUT));
        let bench = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        battle.sides[0].mons[2] = bench;
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        step(&mut battle, [[switch_to(2), no_move()], [no_move(), no_move()]]);
        step(&mut battle, [[switch_to(0), no_move()], [no_move(), no_move()]]);
        let hp_before = battle.sides[1].mons[0].hp;
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert!(battle.sides[1].mons[0].hp < hp_before, "Fake Out should work again after switching back in");
    }

