    #[test]
    fn synchronize_reflects_a_status_back_onto_the_inflicter() {
        use engine_data::abilities_table::ability_ids;

        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::THUNDERWAVE));
        let mut defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        defender.ability = ability_ids::SYNCHRONIZE;
        let mut battle = test_battle(
            [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );

        battle.rng = Rng::new(2);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[1].mons[0].status, Status::Paralysis, "the target itself should still be paralyzed");
        assert_eq!(battle.sides[0].mons[0].status, Status::Paralysis, "Synchronize should reflect the same status onto the inflicter");
    }

    #[test]
    fn synchronize_does_not_react_to_its_own_self_inflicted_status() {
        use engine_data::abilities_table::ability_ids;


        let mut mon = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        mon.ability = ability_ids::SYNCHRONIZE;
        mon.status = Status::Paralysis;
        let mut battle = test_battle(
            [mon, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let actor = Actor { side: 0, slot: 0 };
        { let mut r = battle.rng; crate::abilities::synchronize_reaction(&mut battle, actor, actor, Status::Paralysis, &mut r); battle.rng = r; }


        assert_eq!(battle.sides[0].mons[0].status, Status::Paralysis);
    }

