    #[test]
    fn unburden_doubles_speed_once_an_item_is_actually_consumed() {
        use engine_data::abilities_table::ability_ids;
        use engine_data::items_table::item_ids;

        let mut holder = test_mon([Some(Type::Normal), None], [1, 1, 1, 1, 50], [0; 4]);
        holder.ability = ability_ids::UNBURDEN;
        holder.item = item_ids::SITRUSBERRY;
        holder.hp = holder.max_hp / 2;
        let faster_without_item_loss = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 90], [0; 4]);
        let mut battle = test_battle(
            [holder, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [faster_without_item_loss, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let target = Actor { side: 0, slot: 0 };
        apply_damage(crate::rules::Rules::of(crate::rules::Format::ChampionsMC), mon_at_mut(&mut battle, target), 1);
        assert_eq!(mon_at(&battle, target).item, crate::ids::NONE_ID, "sanity: the berry really was consumed");
        let mut rng = Rng::new(1);
        let ordered = turn_order(&battle, [[no_move(), no_move()], [no_move(), no_move()]], &mut rng);
        assert_eq!(ordered[0].0, target, "Unburden's x2 speed (50 -> 100) should outrun the 90-speed foe once the item is gone");
    }

    #[test]
    fn unburden_does_not_trigger_for_a_mon_that_never_held_an_item() {
        use engine_data::abilities_table::ability_ids;

        let mut holder = test_mon([Some(Type::Normal), None], [1, 1, 1, 1, 50], [0; 4]);
        holder.ability = ability_ids::UNBURDEN;


        let faster = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 90], [0; 4]);
        let battle = test_battle(
            [holder, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [faster, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let mut rng = Rng::new(1);
        let ordered = turn_order(&battle, [[no_move(), no_move()], [no_move(), no_move()]], &mut rng);
        assert_eq!(ordered[0].0, Actor { side: 1, slot: 0 }, "no item ever consumed, so no Unburden boost - the 90-speed foe should still outrun the 50-speed holder");
    }

