    #[test]
    fn flash_fire_boosts_a_fire_move_once_the_volatile_is_already_set() {
        use engine_data::abilities_table::ability_ids;

        fn run_with_volatile(active: bool) -> u16 {
            let mut attacker = test_mon([Some(Type::Fire), None], [100, 100, 100, 100, 100], moves_with(move_ids::FLAMETHROWER));
            attacker.ability = ability_ids::FLASHFIRE;
            if active {
                attacker.volatiles.set(volatile_flags::FLASHFIRE);
            }
            let defender = test_mon([Some(Type::Water), None], [100, 100, 100, 100, 100], [0; 4]);
            let mut battle = test_battle(
                [attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
                1,
            );
            let hp_before = battle.sides[1].mons[0].hp;
            step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
            hp_before - battle.sides[1].mons[0].hp
        }

        let without = run_with_volatile(false);
        let with = run_with_volatile(true);
        assert!(with > without, "Flash Fire's volatile should boost the attacker's own later Fire move: {with} vs {without}");
    }

