    #[test]
    fn choice_scarf_boosts_speed_by_half() {
        use engine_data::items_table::item_ids;

        fn run_with_item(item: u16) -> u32 {
            let mut mon = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
            mon.item = item;
            effective_speed(&crate::side::SideConds::default(), &mon, crate::field::Weather::None, crate::field::Terrain::None, &crate::rules::Rules::CHAMPIONS_MC)
        }

        let without = run_with_item(crate::ids::NONE_ID);
        let with_scarf = run_with_item(item_ids::CHOICESCARF);
        assert_eq!(with_scarf, without * 3 / 2, "Choice Scarf should give exactly 1.5x Speed");
    }

    #[test]
