        use engine_data::items_table::item_ids;
        let mut mon = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let base = effective_speed(&crate::side::SideConds::default(), &mon, crate::field::Weather::None, crate::field::Terrain::None, &crate::rules::Rules::CHAMPIONS_MC);
        mon.item = item_ids::CHOICESCARF;
        mon.ability = engine_data::abilities_table::ability_ids::KLUTZ;
        let speed = effective_speed(&crate::side::SideConds::default(), &mon, crate::field::Weather::None, crate::field::Terrain::None, &crate::rules::Rules::CHAMPIONS_MC);
