    #[test]
    fn white_herb_combines_two_stats_from_the_same_move_before_clearing_either() {







        use engine_data::abilities_table::ability_ids;
        use engine_data::items_table::item_ids;

        let mut holder = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        holder.ability = ability_ids::DEFIANT;
        holder.item = item_ids::WHITEHERB;
        let mut battle = test_battle(
            [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            [holder, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])],
            1,
        );
        let actor = Actor { side: 0, slot: 0 };
        let target = Actor { side: 1, slot: 0 };
        let deltas = [-1, -1, 0, 0, 0, 0, 0];
        let applied = crate::abilities::block_external_boosts(&mut battle, actor, target, deltas, &mut Rng::new(1));
        apply_boosts(mon_at_mut(&mut battle, target), applied);
        crate::abilities::react_to_lowered_boost(&mut battle, actor, target, applied, &mut Rng::new(1));
        check_white_herb_for_all_actives(&mut battle);
        assert_eq!(mon_at(&battle, target).boosts[Stat::Atk as usize], 3, "Defiant's two reactions should land on the still-negative Atk before White Herb clears anything");
        assert_eq!(mon_at(&battle, target).boosts[Stat::Def as usize], 0, "Def was never reaction-boosted, so it's still negative when White Herb runs - cleared to 0");
        assert_eq!(mon_at(&battle, target).item, crate::ids::NONE_ID, "and the item is consumed");
    }

