    #[test]
    fn dragon_darts_takes_the_targets_partner_unless_follow_me_redirects_it() {
        let mon = || test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let mut battle = test_battle([mon(), mon()], [mon(), mon()], 1);
        let actor = Actor { side: 0, slot: 0 };
        let move_data = *moves_table::get(move_ids::DRAGONDARTS);
        let targets = resolve_targets(&battle, actor, &move_data, move_ids::DRAGONDARTS, 1);
        assert_eq!(targets, [Some(Actor { side: 1, slot: 1 }), Some(Actor { side: 1, slot: 0 }), None], "chosen foe first, then its partner");

        battle.sides[1].active_mon_mut(0).volatiles.set(volatile_flags::FOLLOWME);
        let targets = resolve_targets(&battle, actor, &move_data, move_ids::DRAGONDARTS, 1);
        assert_eq!(targets, [Some(Actor { side: 1, slot: 0 }), None, None]);

        battle.sides[1].active_mon_mut(0).volatiles.clear(volatile_flags::FOLLOWME);
        let targets = resolve_targets(&battle, actor, &move_data, move_ids::DRAGONDARTS, 3);
        assert_eq!(targets, [Some(Actor { side: 0, slot: 1 }), None, None]);
    }

