    #[test]
    fn solar_beam_skips_the_charge_in_sun_and_is_halved_in_other_weather() {
        let attacker = test_mon([Some(Type::Grass), None], [100, 100, 100, 100, 100], moves_with(move_ids::SOLARBEAM));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle = test_battle([attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], 1);
        battle.field.weather = crate::field::Weather::Sun;

        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert!(battle.sides[1].mons[0].hp < 200, "in sun Solar Beam attacks on turn one");
        assert!(!battle.sides[0].mons[0].volatiles.has(volatile_flags::CHARGING));

        let attacker = test_mon([Some(Type::Grass), None], [100, 100, 100, 100, 100], moves_with(move_ids::SOLARBEAM));
        let mon = &attacker;
        assert_eq!(base_power_for_move(move_ids::SOLARBEAM, moves_table::get(move_ids::SOLARBEAM), mon, mon), 120);
        assert_eq!(solar_weakened_modifier(move_ids::SOLARBEAM, crate::field::Weather::Rain), Some((1, 2)));
        assert_eq!(solar_weakened_modifier(move_ids::SOLARBEAM, crate::field::Weather::Snow), Some((1, 2)));
        assert_eq!(solar_weakened_modifier(move_ids::SOLARBEAM, crate::field::Weather::Sun), None);
        assert_eq!(crate::damage::apply_base_power_stage(125, [Some((1, 2)), None, None, None, None, None, None, None, None, None, None, None, None, None, None, None, None, None, None, None]), 62, "Solar Blade's 125 halves to 62 through `modify`'s rounding");
    }

    #[test]
    fn hp_and_status_based_base_powers() {
        let mut user = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let foe = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let bp = |id: u16, a: &Mon, d: &Mon| base_power_for_move(id, moves_table::get(id), a, d);

        for (hp, want) in [(200, 20), (100, 40), (60, 80), (30, 100), (15, 150), (1, 200)] {
            user.hp = hp;
            assert_eq!(bp(move_ids::FLAIL, &user, &foe), want, "Flail at {hp}/200");
            assert_eq!(bp(move_ids::REVERSAL, &user, &foe), want);
        }

        let mut target = foe;
        assert_eq!(bp(move_ids::HARDPRESS, &user, &target), 100);
        target.hp = target.max_hp / 2;
        assert_eq!(bp(move_ids::HARDPRESS, &user, &target), 50);
        target.hp = 1;
        assert_eq!(bp(move_ids::HARDPRESS, &user, &target), 1);

        user.status = Status::Burn;
        assert_eq!(status_doubled_modifier(move_ids::FACADE, &user, &foe), Some((2, 1)));
        user.status = Status::Sleep;
        assert_eq!(status_doubled_modifier(move_ids::FACADE, &user, &foe), None);
        target.status = Status::Toxic;
        assert_eq!(status_doubled_modifier(move_ids::VENOSHOCK, &user, &target), Some((2, 1)));
    }

    #[test]
    fn speed_and_turn_order_based_base_powers() {
        let fast = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 400], [0; 4]);
        let slow = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let battle = test_battle([fast, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [slow, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], 1);
        let (me, them) = (Actor { side: 0, slot: 0 }, Actor { side: 1, slot: 0 });
        assert_eq!(battle_base_power(&battle, me, them, move_ids::ELECTROBALL, 0), 150, "4x as fast");
        assert_eq!(battle_base_power(&battle, them, me, move_ids::ELECTROBALL, 0), 40);
        assert_eq!(battle_base_power(&battle, them, me, move_ids::GYROBALL, 0), 101, "25 * 400 / 100 + 1");
        assert_eq!(battle_base_power(&battle, me, them, move_ids::GYROBALL, 0), 7, "25 * 100 / 400 + 1");
        let mut battle = battle;
        battle.sides[1].mons[0].turns_active = 1;
        assert_eq!(battle_base_power(&battle, me, them, move_ids::PAYBACK, 50), 50, "target hasn't acted");
        battle.sides[1].mons[0].volatiles.set(volatile_flags::ACTED_THIS_TURN);
        assert_eq!(battle_base_power(&battle, me, them, move_ids::PAYBACK, 50), 100, "target already acted");
        battle.sides[1].mons[0].turns_active = 0;
        assert_eq!(battle_base_power(&battle, me, them, move_ids::PAYBACK, 50), 50, "it just switched in");
    }

    #[test]
    fn hyper_beam_leaves_its_user_recharging_the_turn_after_it_connects() {
        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], moves_with(move_ids::HYPERBEAM));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 100], [0; 4]);
        let mut battle = test_battle([attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], 1);


        battle.rng = Rng::new(2);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert!(battle.sides[1].mons[0].hp < 200, "Hyper Beam connects (seed 2 is a hit)");
        assert!(battle.sides[0].mons[0].volatiles.has(volatile_flags::MUSTRECHARGE));



        step(&mut battle, [[mv(1, 0), no_move()], [no_move(), no_move()]]);
        assert!(!battle.sides[0].mons[0].volatiles.has(volatile_flags::MUSTRECHARGE));
        assert_eq!(battle.sides[0].mons[0].protect_counter, 0, "the recharge turn took no move at all");

        let hp_before = battle.sides[1].mons[0].hp;
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert!(battle.sides[1].mons[0].hp < hp_before, "and the mon attacks again the turn after");
    }
    #[test]
    fn encore_locks_the_target_into_its_last_move_for_its_next_turns() {




        let attacker = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 200], moves_with(move_ids::ENCORE));
        let defender = test_mon([Some(Type::Normal), None], [100, 100, 100, 100, 1], [move_ids::TACKLE, move_ids::SWORDSDANCE, 0, 0]);
        let mut battle = test_battle([attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], 1);

        step(&mut battle, [[no_move(), no_move()], [mv(0, 0), no_move()]]);
        assert_eq!(battle.sides[1].mons[0].last_move, move_ids::TACKLE);

        step(&mut battle, [[mv(0, 0), no_move()], [mv(1, 0), no_move()]]);
        assert_eq!(battle.sides[1].mons[0].encore_move, move_ids::TACKLE, "locked into Tackle, not Swords Dance");
        assert_eq!(battle.sides[1].mons[0].encore_turns, 2, "3 at start (target hadn't acted yet), minus this turn's residual");
        assert_eq!(battle.sides[1].mons[0].boosts[0], 0, "the Swords Dance choice never went off");
        assert!(battle.sides[0].mons[0].hp < 200, "the encored Tackle hit the attacker");
    }

