        let mut battle = test_battle([user, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [test_mon([Some(Type::Normal), None], [1; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], 1);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[0].mons[0].hp, 200, "Roost heals half max HP");
