        assert_eq!(battle.sides[1].side_conditions.reflect_turns, 0);
        assert_eq!(battle.sides[1].side_conditions.light_screen_turns, 0);

        let singer = test_mon([Some(Type::Water), None], [100; 5], moves_with(move_ids::LIFEDEW));
