    #[test]
    fn conditional_base_powers_follow_item_status_and_weight() {
        let attacker = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let mut with_item = attacker;
        with_item.item = engine_data::items_table::item_ids::LEFTOVERS;
        let defender = test_mon([Some(Type::Normal), None], [100; 5], [0; 4]);
        let bp = |id: u16, a: &Mon, d: &Mon| base_power_for_move(id, moves_table::get(id), a, d);
        assert_eq!(bp(move_ids::ACROBATICS, &attacker, &defender), 110, "no item doubles Acrobatics");
        assert_eq!(bp(move_ids::ACROBATICS, &with_item, &defender), 55);
        let mut burned = defender;
        burned.status = Status::Burn;
        assert_eq!(bp(move_ids::HEX, &attacker, &burned), 130);
        assert_eq!(bp(move_ids::HEX, &attacker, &defender), 65);
        assert_eq!(bp(move_ids::GRASSKNOT, &attacker, &defender), bp(move_ids::LOWKICK, &attacker, &defender), "same weight bands as Low Kick");
    }

    #[test]
    fn foul_play_uses_the_targets_attack_and_psyshock_hits_defense() {
        let hit = |attacker_atk: u16, defender_atk: u16, move_id: u16, defender_def: u16, defender_spd: u16| {
            let attacker = test_mon([Some(Type::Dark), None], [attacker_atk, 100, 100, 100, 100], [move_id, 0, 0, 0]);
            let defender = test_mon([Some(Type::Normal), None], [defender_atk, defender_def, 1, defender_spd, 1], [0; 4]);
            let mut battle = test_battle([attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [defender, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], 1);
            step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
            200 - battle.sides[1].mons[0].hp
        };
        assert_eq!(hit(1, 150, move_ids::FOULPLAY, 100, 100), hit(200, 150, move_ids::FOULPLAY, 100, 100), "the user's own Attack is irrelevant");
        assert!(hit(1, 200, move_ids::FOULPLAY, 100, 100) > hit(1, 50, move_ids::FOULPLAY, 100, 100));

        assert_eq!(hit(100, 100, move_ids::PSYSHOCK, 100, 50), hit(100, 100, move_ids::PSYSHOCK, 100, 200));
        assert!(hit(100, 100, move_ids::PSYSHOCK, 50, 100) > hit(100, 100, move_ids::PSYSHOCK, 200, 100));
    }
    #[test]
    fn a_fixed_multi_hit_move_lands_every_hit_and_reports_each() {
        let attacker = test_mon([Some(Type::Flying), None], [100; 5], moves_with(move_ids::TWINBEAM));
        let mut battle = test_battle([attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [test_mon([Some(Type::Normal), None], [100; 5], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], 1);
        let hits = step_with_hits(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let records: Vec<_> = hits.iter().flatten().collect();
        assert_eq!(records.len(), 2, "Twin Beam is two hits, two records");
        let total: i64 = records.iter().map(|r| r.damage_dealt).sum();
        assert_eq!(200 - battle.sides[1].mons[0].hp as i64, total, "the target lost exactly the two hits' damage");
    }

    #[test]
    fn a_ranged_multi_hit_move_draws_its_count_from_the_weighted_table() {
        let mut counts = [0u32; 6];
        for seed in 0..400 {
            let attacker = test_mon([Some(Type::Ice), None], [100; 5], moves_with(move_ids::ICICLESPEAR));
            let mut battle = test_battle([attacker, test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], [test_mon([Some(Type::Normal), None], [100, 1000, 1, 1000, 1], [0; 4]), test_mon([Some(Type::Normal), None], [1; 5], [0; 4])], seed);
            battle.sides[1].mons[0].hp = 60000;
            battle.sides[1].mons[0].max_hp = 60000;
            let hits = step_with_hits(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
            counts[hits.iter().flatten().count()] += 1;
        }
        assert_eq!(counts[0] + counts[1], 0);

        assert!(counts[2] > 100 && counts[3] > 100 && counts[4] > 30 && counts[5] > 30, "{counts:?}");
        assert!(counts[2] + counts[3] > counts[4] + counts[5]);
    }
