    #[test]
    fn early_bird_wakes_twice_as_fast() {
        use engine_data::abilities_table::ability_ids;

        let mut battle = a2_pair(ability_ids::EARLYBIRD, ability_ids::PRESSURE, move_ids::TACKLE);
        battle.sides[0].mons[0].status = Status::Sleep;
        battle.sides[0].mons[0].status_counter = 3;
        let hp = battle.sides[1].mons[0].hp;
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert_eq!((battle.sides[0].mons[0].status, battle.sides[0].mons[0].status_counter), (Status::Sleep, 1));
        assert_eq!(battle.sides[1].mons[0].hp, hp, "still asleep");
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[0].mons[0].status, Status::None);
        assert!(battle.sides[1].mons[0].hp < hp, "woke up and attacked");

        let mut plain = a2_pair(ability_ids::PRESSURE, ability_ids::PRESSURE, move_ids::TACKLE);
        plain.sides[0].mons[0].status = Status::Sleep;
        plain.sides[0].mons[0].status_counter = 3;
        for _ in 0..2 {
            step(&mut plain, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        }
        assert_eq!((plain.sides[0].mons[0].status, plain.sides[0].mons[0].status_counter), (Status::Sleep, 1));
    }

    #[test]
    fn corrosion_poisons_steel_and_poison_types() {
        use engine_data::abilities_table::ability_ids;
        let mut battle = a2_pair(ability_ids::CORROSION, ability_ids::PRESSURE, move_ids::TACKLE);
        let (user, target) = (Actor { side: 0, slot: 0 }, Actor { side: 1, slot: 0 });
        for (types, status) in [([Some(Type::Steel), None, None], Status::Poison), ([Some(Type::Poison), None, None], Status::Toxic)] {
            mon_at_mut(&mut battle, target).types = types;
            mon_at_mut(&mut battle, target).status = Status::None;
            { let mut r = battle.rng; try_set_status(&mut battle, user, target, status, &mut r); battle.rng = r; }
            assert_eq!(mon_at(&battle, target).status, status);
        }

        mon_at_mut(&mut battle, target).types = [Some(Type::Fire), None, None];
        mon_at_mut(&mut battle, target).status = Status::None;
        { let mut r = battle.rng; try_set_status(&mut battle, user, target, Status::Burn, &mut r); battle.rng = r; }
        assert_eq!(mon_at(&battle, target).status, Status::None);
        mon_at_mut(&mut battle, user).ability = ability_ids::PRESSURE;
        mon_at_mut(&mut battle, target).types = [Some(Type::Steel), None, None];
        { let mut r = battle.rng; try_set_status(&mut battle, user, target, Status::Poison, &mut r); battle.rng = r; }
        assert_eq!(mon_at(&battle, target).status, Status::None);
    }

