    #[test]
    fn stall_moves_last_in_its_priority_bracket() {
        use engine_data::abilities_table::ability_ids;
        let mut battle = a2_pair(ability_ids::PRESSURE, ability_ids::PRESSURE, move_ids::TACKLE);
        let (fast, slow) = (Actor { side: 0, slot: 0 }, Actor { side: 1, slot: 0 });
        assert!(sort_key(&battle, fast, mv(0, 0)) > sort_key(&battle, slow, mv(0, 0)));
        battle.sides[0].mons[0].ability = ability_ids::STALL;
        battle.sides[0].mons[0].flags.set(mon_flags::STALL_SLOW);
        assert!(sort_key(&battle, fast, mv(0, 0)) < sort_key(&battle, slow, mv(0, 0)));
        battle.sides[0].mons[0].flags.set(mon_flags::QUICK_CLAW);
        assert!(sort_key(&battle, fast, mv(0, 0)) > sort_key(&battle, slow, mv(0, 0)), "a Quick Claw roll overrides it");
    }

    #[test]
    fn mycelium_might_status_moves_go_last_and_skip_quick_claw() {

        use engine_data::abilities_table::ability_ids;
        let mut battle = a2_pair(ability_ids::MYCELIUMMIGHT, ability_ids::PRESSURE, move_ids::TACKLE);
        let actor = Actor { side: 0, slot: 0 };
        battle.sides[0].mons[0].item = engine_data::items_table::item_ids::QUICKCLAW;
        let (mut status_claws, mut tackle_claws) = (0, 0);
        for seed in 0..200 {
            let mut rng = Rng::new(seed);
            roll_quick_claw(&mut battle, actor, move_ids::SWORDSDANCE, &mut rng);
            let m = &battle.sides[0].mons[0];
            assert!(m.flags.has(mon_flags::STALL_SLOW), "a Status move under Mycelium Might is -0.1");
            status_claws += m.flags.has(mon_flags::QUICK_CLAW) as u32;
            roll_quick_claw(&mut battle, actor, move_ids::TACKLE, &mut rng);
            assert!(!battle.sides[0].mons[0].flags.has(mon_flags::STALL_SLOW), "an attack keeps its bracket place");
            tackle_claws += battle.sides[0].mons[0].flags.has(mon_flags::QUICK_CLAW) as u32;
        }
        assert_eq!(status_claws, 0, "no Quick Claw roll for a Mycelium Might Status move");
        assert!(tackle_claws > 10, "Quick Claw still rolls for its attacks ({tackle_claws} of 200)");
    }

