    #[test]
    fn shed_shell_slips_a_shadow_tag() {
        use engine_data::abilities_table::ability_ids;
        use engine_data::items_table::item_ids;
        let mut battle = a2_pair(ability_ids::SHADOWTAG, ability_ids::PRESSURE, move_ids::TACKLE);
        battle.sides[1].mons[0].item = item_ids::SHEDSHELL;
        assert!(!is_trapped(&battle, Actor { side: 1, slot: 0 }));
    }

    #[test]
    fn shell_bell_heals_an_eighth_of_the_damage() {
        use engine_data::abilities_table::ability_ids;
        use engine_data::items_table::item_ids;
        let mut battle = a2_pair(ability_ids::PRESSURE, ability_ids::PRESSURE, move_ids::TACKLE);
        let m = &mut battle.sides[0].mons[0];
        (m.item, m.hp) = (item_ids::SHELLBELL, 10);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        let dealt = battle.sides[1].mons[0].max_hp - battle.sides[1].mons[0].hp;
        assert_eq!(battle.sides[0].mons[0].hp, 10 + (dealt / 8).max(1));
    }

    #[test]
    fn receiver_takes_a_fainted_allys_ability_and_starts_it() {
        use engine_data::abilities_table::ability_ids;
        let mut battle = a2_pair(ability_ids::PRESSURE, ability_ids::PRESSURE, move_ids::TACKLE);
        battle.sides[0].mons[0].ability = ability_ids::RECEIVER;
        battle.sides[0].mons[1].ability = ability_ids::INTIMIDATE;
        let before = [[false; 4]; 2];
        let partner = &mut battle.sides[0].mons[1];
        partner.hp = 0;
        partner.flags.set(mon_flags::FAINTED);
        push_faint_events(&mut battle, before, &mut crate::rng::Rng::new(0));
        assert_eq!(battle.sides[0].mons[0].ability, ability_ids::INTIMIDATE);
        assert_eq!(battle.sides[1].mons[0].boosts[0], -1, "the received Intimidate went off");
    }

    #[test]
    fn electromorphosis_charges_the_next_electric_move() {
        use engine_data::abilities_table::ability_ids;
        let mut battle = a2_pair(ability_ids::PRESSURE, ability_ids::ELECTROMORPHOSIS, move_ids::TACKLE);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert!(battle.sides[1].mons[0].volatiles.has(volatile_flags::CHARGE), "still charged after the turn it was gained");
        step(&mut battle, [[no_move(), no_move()], [no_move(), no_move()]]);
        assert!(battle.sides[1].mons[0].volatiles.has(volatile_flags::CHARGE), "still charged a turn later (no duration in gen 9: only an Electric move spends it)");
    }

    #[test]
    fn the_charge_move_does_not_spend_its_own_charge() {
        use engine_data::abilities_table::ability_ids;

        let mut battle = a2_pair(ability_ids::PRESSURE, ability_ids::PRESSURE, move_ids::CHARGE);
        step(&mut battle, [[mv(0, 0), no_move()], [no_move(), no_move()]]);
        assert!(battle.sides[0].mons[0].volatiles.has(volatile_flags::CHARGE), "charged after using Charge");
    }

    #[test]
    fn charge_is_spent_by_an_electric_move_that_finds_no_target() {

        use engine_data::abilities_table::ability_ids;
        let mut battle = a2_pair(ability_ids::PRESSURE, ability_ids::PRESSURE, move_ids::THUNDERBOLT);
        battle.sides[0].mons[0].volatiles.set(volatile_flags::CHARGE);
        let partner = &mut battle.sides[0].mons[1];
        partner.hp = 0;
        partner.flags.set(mon_flags::FAINTED);
        step(&mut battle, [[mv(0, 3), no_move()], [no_move(), no_move()]]);
        assert_eq!(battle.sides[1].mons[0].hp, battle.sides[1].mons[0].max_hp, "nothing was hit");
        assert!(!battle.sides[0].mons[0].volatiles.has(volatile_flags::CHARGE), "the charge is gone");
    }

